                                            {lesson.is_visible ? "إخفاء" : "إظهار"}
                                        </button>
                                        <button
                                            className={styles["btnAction"]}
                                            onClick={() => handleEdit(lesson)}
                                        >
                                            تعديل
                                        </button>
                                        <button
                                            className={`${styles["btnAction"]} ${styles["btnDelete"]}`}
                                            onClick={() => confirmDeleteLesson(Number(lesson.id))}
