"use client";

import React, { useEffect, useState } from "react";
import { useRouter, useParams } from "next/navigation";
import Toast from "@/components/Toast";
import styles from "./AdminChapters.module.css";
import "@/styles/toast.css";
import { getCourseChapters, deleteChapter, createChapter, updateChapter, type Chapter } from "@/utils/chapterService";

export default function AdminChaptersPage() {
    const router = useRouter();
    const params = useParams();
    const courseId = params.id as string;

    const [chapters, setChapters] = useState<Chapter[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    const [toastVisible, setToastVisible] = useState(false);
    const [toastMessage, setToastMessage] = useState("");
    const [toastType, setToastType] = useState<"success" | "error" | "warning" | "info" | "confirm">("info");
    const [searchQuery, setSearchQuery] = useState<string>('');
    const [pendingDeleteChapterId, setPendingDeleteChapterId] = useState<number | null>(null);
    const [isDeletingChapterId, setIsDeletingChapterId] = useState<number | null>(null);

    const [showModal, setShowModal] = useState(false);
    const [modalMode, setModalMode] = useState<"create" | "edit">("create");
    const [editingChapter, setEditingChapter] = useState<Chapter | null>(null);
    const [formData, setFormData] = useState({
        title: "",
        description: "",
        order: 1
    });

    const fetchData = async () => {
        setLoading(true);
        setError(null);
        try {
            const list = await getCourseChapters(courseId);
            setChapters(list);
        } catch (err: any) {
            setError(err?.message || "فشل في جلب الفصول");
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchData();
    }, [courseId]);

    const confirmDeleteChapter = (chapterId: number) => {
        setPendingDeleteChapterId(chapterId);
        setToastMessage("هل أنت متأكد من حذف هذا الفصل؟");
        setToastType("confirm");
        setToastVisible(true);
    };

    const performDeleteChapter = async () => {
        if (!pendingDeleteChapterId) return;
        const chapterId = pendingDeleteChapterId;
        try {
            setIsDeletingChapterId(chapterId);
            await deleteChapter(chapterId);
            setChapters((prev) => prev.filter((c) => Number(c.id) !== Number(chapterId)));
            setToastType("success");
            setToastMessage("تم حذف الفصل بنجاح");
            setToastVisible(true);
        } catch (err: any) {
            setToastType("error");
            setToastMessage(err?.message || "فشل في حذف الفصل");
            setToastVisible(true);
        } finally {
            setIsDeletingChapterId(null);
            setPendingDeleteChapterId(null);
        }
    };

    const handleCreate = () => {
        setModalMode("create");
        setFormData({
            title: "",
            description: "",
            order: chapters.length + 1
        });
        setShowModal(true);
    };

    const handleEdit = (chapter: Chapter) => {
        setModalMode("edit");
        setEditingChapter(chapter);
        setFormData({
            title: chapter.title,
            description: chapter.description || "",
            order: chapter.order
        });
        setShowModal(true);
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        try {
            if (modalMode === "create") {
                const newChapter = await createChapter(courseId, formData);
                setChapters((prev) => [...prev, newChapter]);
                setToastType("success");
                setToastMessage("تم إضافة الفصل بنجاح");
            } else if (editingChapter) {
                const updatedChapter = await updateChapter(editingChapter.id, formData);
                setChapters((prev) => prev.map((c) => c.id === updatedChapter.id ? updatedChapter : c));
                setToastType("success");
                setToastMessage("تم تعديل الفصل بنجاح");
            }
            setToastVisible(true);
            setShowModal(false);
            setEditingChapter(null);
        } catch (err: any) {
            setToastType("error");
            setToastMessage(err?.message || "فشل في حفظ الفصل");
            setToastVisible(true);
        }
    };

    const filteredChapters = chapters.filter((chapter) => {
        if (!searchQuery.trim()) return true;
        const query = searchQuery.toLowerCase();
        return (
            chapter.title?.toLowerCase().includes(query) ||
            chapter.description?.toLowerCase?.().includes(query)
        );
    });

    return (
        <div className={styles["admin-chapters-container"]}>
            <div className={styles["admin-chapters-header"]}>
                <div>
                    <h1 className={styles["admin-chapters-title"]}>إدارة الفصول</h1>
                    <p className={styles["admin-chapters-subtitle"]}>إدارة وتنظيم فصول الكورس</p>
                </div>
                <button
                    className={styles["btn-back"]}
                    onClick={() => router.push("/admin/course-management")}
                >
                    ← رجوع
                </button>
            </div>

            <div className={styles["admin-chapters-actions"]}>
                <button
                    className={styles["btn-primary"]}
                    onClick={handleCreate}
                >
                    + إضافة فصل جديد
                </button>
            </div>

            {/* Search Bar */}
            <div className={styles["searchContainer"]}>
                <div className={styles["searchIcon"]}>🔍</div>
                <input
                    type="text"
                    placeholder="بحث عن فصل..."
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    className={styles["searchInput"]}
                />
                {searchQuery && (
                    <button
                        className={styles["clearSearch"]}
                        onClick={() => setSearchQuery('')}
                        aria-label="مسح البحث"
                    >
                        ×
                    </button>
                )}
            </div>

            {loading && (
                <div className={styles["loading"]}>
                    <div>
                        <div className={styles["spinner"]}></div>
                        <div className={styles["loading-text"]}>جاري تحميل الفصول...</div>
                    </div>
                </div>
            )}

            {error && (
                <div className={`${styles["message"]} ${styles["message-error"]}`}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                        <span style={{ fontSize: '1.2rem' }}>⚠️</span>
                        <div>
                            <strong>خطأ في التحميل:</strong>
                            <div style={{ marginTop: '5px' }}>{error}</div>
                        </div>
                    </div>
                </div>
            )}

            {!loading && !error && (
                <div className={styles["chapters-table-container"]} dir="rtl">
                    <table className={styles["chapters-table"]}>
                        <thead>
                            <tr>
                                <th className={styles["chapter-title-cell"]}>العنوان</th>
                                <th className={styles["chapter-description-cell"]}>الوصف</th>
                                <th className={styles["chapter-order-cell"]}>الترتيب</th>
                                <th className={styles["chapter-lessons-count-cell"]}>عدد الدروس</th>
                                <th className={styles["actionsCell"]}>إجراءات</th>
                            </tr>
                        </thead>
                        <tbody>
                            {filteredChapters.map((chapter) => (
                                <tr key={String(chapter.id)}>
                                    <td>
                                        <div className={styles["chapter-title"]}>
                                            {chapter.title}
                                        </div>
                                    </td>
                                    <td>
                                        <div className={styles["chapter-description"]}>
                                            {chapter.description || "—"}
                                        </div>
                                    </td>
                                    <td>
                                        <span className={styles["chapter-order"]}>
                                            {chapter.order}
                                        </span>
                                    </td>
                                    <td>
                                        <span className={styles["chapter-lessons-count"]}>
                                            {chapter.lessons_count || 0}
                                        </span>
                                    </td>
                                    <td className={styles["actionsCell"]}>
                                        <div className={styles["table-actions"]}>
                                            <button
                                                className={`${styles["btn-small"]} ${styles["btn-lessons"]}`}
                                                onClick={() => router.push(`/admin/courses/${courseId}/chapters/${chapter.id}/lessons`)}
                                            >
                                                إدارة الدروس
                                            </button>
                                            <button
                                                className={`${styles["btn-small"]} ${styles["btn-edit"]}`}
                                                onClick={() => handleEdit(chapter)}
                                            >
                                                تعديل
                                            </button>
                                            <button
                                                className={`${styles["btn-small"]} ${styles["btn-delete"]}`}
                                                onClick={() => confirmDeleteChapter(Number(chapter.id))}
                                                disabled={isDeletingChapterId === Number(chapter.id)}
                                            >
                                                {isDeletingChapterId === Number(chapter.id) ? "جاري الحذف..." : "حذف"}
                                            </button>
                                        </div>
                                    </td>
                                </tr>
                            ))}
                            {filteredChapters.length === 0 && (
                                <tr>
                                    <td colSpan={5}>
                                        <div className={styles["empty-state"]}>
                                            <div className={styles["empty-state-icon"]}>📖</div>
                                            <div className={styles["empty-state-title"]}>لا توجد فصول</div>
                                            <div className={styles["empty-state-description"]}>لم يتم إنشاء أي فصول بعد. ابدأ بإنشاء فصل جديد.</div>
                                        </div>
                                    </td>
                                </tr>
                            )}
                        </tbody>
                    </table>
                </div>
            )}

            {/* Modal */}
            {showModal && (
                <div className={styles["modal-overlay"]} onClick={() => setShowModal(false)}>
                    <div className={styles["modal-content"]} onClick={(e) => e.stopPropagation()}>
                        <div className={styles["modal-header"]}>
                            <h2>{modalMode === "create" ? "إضافة فصل جديد" : "تعديل الفصل"}</h2>
                            <button className={styles["modal-close"]} onClick={() => setShowModal(false)}>×</button>
                        </div>
                        <form onSubmit={handleSubmit}>
                            <div className={styles["form-group"]}>
                                <label htmlFor="title">العنوان *</label>
                                <input
                                    type="text"
                                    id="title"
                                    value={formData.title}
                                    onChange={(e) => setFormData({ ...formData, title: e.target.value })}
                                    required
                                    className={styles["form-input"]}
                                />
                            </div>
                            <div className={styles["form-group"]}>
                                <label htmlFor="description">الوصف</label>
                                <textarea
                                    id="description"
                                    value={formData.description}
                                    onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                                    className={styles["form-textarea"]}
                                    rows={4}
                                />
                            </div>
                            <div className={styles["form-group"]}>
                                <label htmlFor="order">الترتيب *</label>
                                <input
                                    type="number"
                                    id="order"
                                    value={formData.order}
                                    onChange={(e) => setFormData({ ...formData, order: parseInt(e.target.value) || 1 })}
                                    required
                                    min="1"
                                    className={styles["form-input"]}
                                />
                            </div>
                            <div className={styles["modal-actions"]}>
                                <button type="button" className={styles["btn-secondary"]} onClick={() => setShowModal(false)}>
                                    إلغاء
                                </button>
                                <button type="submit" className={styles["btn-primary"]}>
                                    {modalMode === "create" ? "إضافة" : "حفظ"}
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}

            <Toast
                message={toastMessage}
                type={toastType}
                isVisible={toastVisible}
                onClose={() => setToastVisible(false)}
                onConfirm={toastType === "confirm" ? performDeleteChapter : undefined}
                onCancel={toastType === "confirm" ? () => { setToastVisible(false); setPendingDeleteChapterId(null); } : undefined}
                duration={4000}
            />
        </div>
    );
}

"use client";

import React, { useEffect, useState, useRef } from "react";
import { useParams, useRouter } from "next/navigation";
import Link from "next/link";
import {
  ArrowRight,
  Save,
  BookOpen,
  User,
  FolderOpen,
  Layers,
  Clock,
  Hash,
  ImagePlus,
  Eye,
  BarChart3,
  Upload,
  CheckCircle,
} from "lucide-react";
import Toast from "@/components/Toast";
import "@/styles/toast.css";
import { getAdminCourse, updateCourse, type Course } from "@/utils/courseService";
import { getAdminCategories, type Diploma } from "@/utils/categoryService";
import { getAdminSections, type Section } from "@/utils/sectionService";
import { getInstructors, type Instructor } from "@/utils/instructorService";
import { getBackendAssetUrl } from "@/utils/url";
import styles from "./EditCourse.module.css";

type CourseWithCoverUrl = Course & { cover_image_url?: string };

export default function EditCoursePage() {
  const router = useRouter();
  const { id } = useParams() as { id: string };
  const courseId = Number(id);

  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [course, setCourse] = useState<Course | null>(null);
  const [diplomas, setDiplomas] = useState<Diploma[]>([]);
  const [sections, setSections] = useState<Section[]>([]);
  const [instructors, setInstructors] = useState<Instructor[]>([]);
  const [isInstructorMenuOpen, setInstructorMenuOpen] = useState(false);
  const [instructorSearch, setInstructorSearch] = useState('');
  const dropdownRef = useRef<HTMLDivElement | null>(null);
  const fileInputRef = useRef<HTMLInputElement | null>(null);

  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [instructorId, setInstructorId] = useState<string>("");
  const [categoryId, setCategoryId] = useState<string>("");
  const [sectionIds, setSectionIds] = useState<string[]>([]);
  const [status, setStatus] = useState<"draft" | "published">("published");
  const [duration, setDuration] = useState<string>("");
  const [coverFile, setCoverFile] = useState<File | null>(null);
  const [coverPreview, setCoverPreview] = useState<string | null>(null);
  const [rank, setRank] = useState<string>('');

  const [toastVisible, setToastVisible] = useState(false);
  const [toastMessage, setToastMessage] = useState("");
  const [toastType, setToastType] = useState<"success" | "error" | "warning" | "info">("info");

  function showToast(msg: string, type: "success" | "error" | "warning" | "info" = "info") {
    setToastMessage(msg);
    setToastType(type);
    setToastVisible(true);
  }

  useEffect(() => {
    async function load() {
      try {
        setLoading(true);
        const [c, cats, ins, secs] = await Promise.all([
          getAdminCourse(courseId),
          getAdminCategories(),
          getInstructors(),
          getAdminSections(),
        ]);
        if (!c) throw new Error("لم يتم العثور على بيانات المقرر");
        setCourse(c);
        setDiplomas(cats);
        setSections(secs);
        const sortedIns = [...ins].sort((a, b) => a.name.localeCompare(b.name, 'ar'));
        setInstructors(sortedIns);
        setTitle(String(c.title ?? ""));
        setDescription(String(c.description ?? ""));
        setInstructorId(String(c.instructor_id ?? c.instructor?.id ?? ""));
        setCategoryId(String(c.category_id ?? c.category?.id ?? ""));
        const existingSections = Array.isArray(c.sections) && c.sections.length > 0
          ? c.sections.map((section) => String(section.id))
          : c.section_id || c.section?.id
            ? [String(c.section_id ?? c.section?.id)]
            : [];
        setSectionIds(existingSections);
        const isPub = (c.is_published === true) || (String(c.status || "published").toLowerCase() === "published");
        setStatus(isPub ? "published" : "draft");
        setDuration(String(c.duration ?? ""));
        setRank(c.rank != null ? String(c.rank) : '');
        const existingCover = getBackendAssetUrl(c.cover_image ?? (c as CourseWithCoverUrl).cover_image_url);
        setCoverPreview(existingCover || null);
      } catch (err: unknown) {
        console.error(err);
        showToast(err instanceof Error ? err.message : "حدث خطأ في تحميل بيانات المقرر", "error");
      } finally {
        setLoading(false);
      }
    }
    if (!Number.isNaN(courseId) && courseId > 0) load();
    else {
      showToast("معرف مقرر غير صالح", "error");
      setLoading(false);
    }
  }, [courseId]);

  function onCoverChange(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0] || null;
    setCoverFile(file);
    setCoverPreview(file ? URL.createObjectURL(file) : coverPreview);
  }

  function toggleSection(sectionId: number) {
    const idValue = String(sectionId);
    setSectionIds((current) => current.includes(idValue)
      ? current.filter((item) => item !== idValue)
      : [...current, idValue]);
  }

  function removeSection(sectionId: number) {
    const idValue = String(sectionId);
    setSectionIds((current) => current.filter((item) => item !== idValue));
  }

  useEffect(() => {
    function handleClickOutside(e: MouseEvent) {
      if (dropdownRef.current && !dropdownRef.current.contains(e.target as Node)) {
        setInstructorMenuOpen(false);
      }
    }
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  async function onSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!title || !description || !instructorId || !categoryId || !duration) {
      showToast("يرجى ملء جميع الحقول الإجبارية بقيم صحيحة", "error");
      return;
    }
    try {
      setSaving(true);
      const fd = new FormData();
      fd.append("title", title);
      fd.append("description", description);
      fd.append("instructor_id", instructorId);
      fd.append("category_id", categoryId);
      if (sectionIds.length > 0) {
        fd.append("section_id", sectionIds[0]);
        fd.append("section_ids", JSON.stringify(sectionIds.map(Number)));
      } else {
        fd.append("section_id", "");
        fd.append("section_ids", JSON.stringify([]));
      }
      fd.append("is_published", status === "published" ? "1" : "0");
      fd.append("duration", duration);
      fd.append("price", "0");
      fd.append("is_free", "1");
      if (rank && rank.trim() !== '') {
        fd.append('rank', rank.trim());
      }
      if (coverFile) fd.append("cover_image", coverFile);
      await updateCourse(courseId, fd);
      showToast("تم تعديل المقرر بنجاح ✅", "success");
      setTimeout(() => {
        const cid = Number(categoryId);
        if (cid) router.push(`/admin/diplomas/${cid}`);
        else router.push("/admin/course-management");
      }, 1200);
    } catch (err: unknown) {
      console.error(err);
      showToast(err instanceof Error ? err.message : "حدث خطأ أثناء حفظ التعديلات", "error");
    } finally {
      setSaving(false);
    }
  }

  function onCancel() {
    const cid = Number(categoryId || course?.category_id || course?.category?.id || 0);
    if (cid) router.push(`/admin/diplomas/${cid}`);
    else router.push("/admin/diplomas");
  }

  // Derived
  const sortedInstructors = [...instructors];
  const selectedInstructor = sortedInstructors.find((i) => String(i.id) === instructorId);
  const filteredInstructors = sortedInstructors.filter((i) => {
    const q = instructorSearch.trim().toLowerCase();
    if (!q) return true;
    return (i.name || "").toLowerCase().includes(q) || (i.title || "").toLowerCase().includes(q);
  });
  const selectedSections = sections.filter((s) => sectionIds.includes(String(s.id)));
  const selectedDiploma = diplomas.find(d => String(d.id) === categoryId);

  if (loading) {
    return (
      <div className={styles.page}>
        <div className={styles.loadingState}>
          <div className={styles.spinner} />
          <span>جاري تحميل بيانات المقرر...</span>
        </div>
      </div>
    );
  }

  if (!course) {
    return (
      <div className={styles.page}>
        <div className={styles.errorState}>
          <span>لا توجد بيانات لهذا المقرر</span>
          <button className={styles.btnSecondary} onClick={() => router.back()}>العودة</button>
        </div>
      </div>
    );
  }

  return (
    <div className={styles.page}>
      {/* ─── Hero ─── */}
      <div className={styles.hero}>
        <div className={styles.heroRow}>
          <div className={styles.heroInfo}>
            <h1>
              ✏️ تعديل المقرر
              <span className={`${styles.heroBadge} ${status === 'published' ? styles.heroBadgePublished : styles.heroBadgeDraft}`}>
                {status === 'published' ? 'منشور' : 'مسودة'}
              </span>
            </h1>
            <p>{course.title} — معرف: {course.id}</p>
          </div>
          <div className={styles.heroActions}>
            <Link href={`/admin/reports/courses/${courseId}`} className={`${styles.heroBtn} ${styles.heroBtnWhite}`}>
              <BarChart3 size={18} />
              التقرير
            </Link>
            <Link href={`/admin/courses/${courseId}/chapters`} className={`${styles.heroBtn} ${styles.heroBtnWhite}`}>
              <Layers size={18} />
              الفصول والدروس
            </Link>
            <button onClick={onCancel} className={`${styles.heroBtn} ${styles.heroBtnGhost}`}>
              <ArrowRight size={18} />
              رجوع
            </button>
          </div>
        </div>
      </div>

      {/* ─── Main Layout ─── */}
      <form onSubmit={onSubmit}>
        <div className={styles.layout}>
          {/* ─── Main Column ─── */}
          <div>
            {/* Basic Info */}
            <div className={styles.card} style={{ marginBottom: '1.5rem' }}>
              <div className={styles.cardHeader}>
                <BookOpen size={20} color="#0ea5e9" />
                <h2>المعلومات الأساسية</h2>
              </div>
              <div className={styles.cardBody}>
                <div className={styles.form}>
                  <div className={styles.field}>
                    <label><span className={styles.required}>*</span> عنوان المقرر</label>
                    <input className={styles.input} value={title} onChange={e => setTitle(e.target.value)} required />
                  </div>

                  <div className={styles.field}>
                    <label><span className={styles.required}>*</span> وصف المقرر</label>
                    <textarea className={styles.textarea} value={description} onChange={e => setDescription(e.target.value)} rows={4} required />
                  </div>

                  <div className={styles.row}>
                    <div className={styles.field} ref={dropdownRef} style={{ position: 'relative' }}>
                      <label><User size={14} /> <span className={styles.required}>*</span> المحاضر</label>
                      <button type="button" className={styles.selectBtn} onClick={() => setInstructorMenuOpen(v => !v)}>
                        {selectedInstructor ? selectedInstructor.name : 'اختر المحاضر'}
                      </button>
                      {isInstructorMenuOpen && (
                        <div className={styles.dropdown}>
                          <div className={styles.dropdownSearch}>
                            <input placeholder="ابحث باسم المحاضر..." value={instructorSearch} onChange={e => setInstructorSearch(e.target.value)} />
                          </div>
                          {filteredInstructors.map(instr => (
                            <div key={instr.id} className={styles.dropdownItem} onClick={() => { setInstructorId(String(instr.id)); setInstructorMenuOpen(false); }}>
                              <div className={styles.dropdownItemName}>{instr.name}</div>
                              {instr.title && <div className={styles.dropdownItemSub}>{instr.title}</div>}
                            </div>
                          ))}
                          {filteredInstructors.length === 0 && <div className={styles.dropdownEmpty}>لا توجد نتائج</div>}
                        </div>
                      )}
                      <select value={instructorId} onChange={e => setInstructorId(e.target.value)} className={styles.hiddenSelect} required aria-hidden="true">
                        <option value="">اختر المحاضر</option>
                        {sortedInstructors.map(i => <option key={i.id} value={i.id}>{i.name}</option>)}
                      </select>
                    </div>

                    <div className={styles.field}>
                      <label><FolderOpen size={14} /> <span className={styles.required}>*</span> الدبلومة</label>
                      <select className={styles.select} value={categoryId} onChange={e => setCategoryId(e.target.value)} required>
                        <option value="">اختر الدبلومة</option>
                        {diplomas.map(d => <option key={d.id} value={d.id}>{d.name}</option>)}
                      </select>
                    </div>
                  </div>
                </div>
              </div>
            </div>

            {/* Sections */}
            <div className={styles.card} style={{ marginBottom: '1.5rem' }}>
              <div className={styles.cardHeader}>
                <Layers size={20} color="#0ea5e9" />
                <h2>أقسام المقرر</h2>
              </div>
              <div className={styles.cardBody}>
                <div className={styles.multiBox}>
                  <div className={styles.multiHeader}>
                    <span className={styles.multiHint}>يمكن ربط المقرر بأكثر من قسم</span>
                    <span className={styles.multiCount}>{selectedSections.length} محدد</span>
                  </div>

                  {selectedSections.length > 0 && (
                    <div className={styles.chips}>
                      {selectedSections.map(s => (
                        <span key={s.id} className={styles.selectedChip}>
                          {s.name}
                          <button type="button" onClick={() => removeSection(s.id)}>×</button>
                        </span>
                      ))}
                    </div>
                  )}

                  <div className={styles.chips}>
                    {sections.map(section => {
                      const isSelected = sectionIds.includes(String(section.id));
                      return (
                        <button
                          key={section.id}
                          type="button"
                          className={`${styles.chip} ${isSelected ? styles.chipSelected : ''}`}
                          onClick={() => toggleSection(section.id)}
                        >
                          {section.name}
                        </button>
                      );
                    })}
                    {sections.length === 0 && <span style={{ color: '#94a3b8', fontSize: '0.9rem' }}>لا توجد أقسام متاحة</span>}
                  </div>
                </div>
              </div>
            </div>

            {/* Settings */}
            <div className={styles.card} style={{ marginBottom: '1.5rem' }}>
              <div className={styles.cardHeader}>
                <Clock size={20} color="#0ea5e9" />
                <h2>الإعدادات</h2>
              </div>
              <div className={styles.cardBody}>
                <div className={styles.form}>
                  <div className={styles.row}>
                    <div className={styles.field}>
                      <label><Clock size={14} /> <span className={styles.required}>*</span> المدة (بالساعات)</label>
                      <input className={styles.input} type="number" min={1} value={duration} onChange={e => setDuration(e.target.value)} required />
                    </div>
                    <div className={styles.field}>
                      <label><Hash size={14} /> الترتيب (اختياري)</label>
                      <input className={styles.input} type="number" min={1} value={rank} onChange={e => setRank(e.target.value)} placeholder="مثال: 1" />
                    </div>
                  </div>
                </div>
              </div>
            </div>

            {/* Cover */}
            <div className={styles.card}>
              <div className={styles.cardHeader}>
                <ImagePlus size={20} color="#0ea5e9" />
                <h2>صورة الغلاف</h2>
              </div>
              <div className={styles.cardBody}>
                <input ref={fileInputRef} type="file" accept="image/*" onChange={onCoverChange} className={styles.fileInput} />
                {coverPreview ? (
                  <div>
                    <img src={coverPreview} alt="معاينة الغلاف" className={styles.coverPreview} />
                    <div style={{ marginTop: '0.75rem' }}>
                      <button type="button" className={styles.btnSecondary} onClick={() => fileInputRef.current?.click()}>
                        <Upload size={16} /> تغيير الصورة
                      </button>
                    </div>
                  </div>
                ) : (
                  <div className={styles.uploadArea} onClick={() => fileInputRef.current?.click()}>
                    <div className={styles.uploadIcon}><ImagePlus size={24} /></div>
                    <div className={styles.uploadText}>
                      <strong>اضغط لرفع صورة</strong><br />
                      PNG, JPG حتى 5MB
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>

          {/* ─── Sidebar ─── */}
          <div className={styles.sidebar}>
            {/* Status */}
            <div className={styles.previewCard}>
              <div className={styles.previewTitle}>حالة النشر</div>
              <div className={styles.statusToggle}>
                <button type="button" className={`${styles.statusOption} ${status === 'published' ? styles.statusOptionActive : ''}`} onClick={() => setStatus('published')}>
                  منشور
                </button>
                <button type="button" className={`${styles.statusOption} ${status === 'draft' ? styles.statusOptionActive : ''}`} onClick={() => setStatus('draft')}>
                  مسودة
                </button>
              </div>
            </div>

            {/* Preview */}
            <div className={styles.previewCard}>
              <div className={styles.previewTitle}>ملخص المقرر</div>
              <div className={styles.previewRow}>
                <span className={styles.previewLabel}>العنوان</span>
                <span className={styles.previewValue}>{title || '—'}</span>
              </div>
              <div className={styles.previewRow}>
                <span className={styles.previewLabel}>المحاضر</span>
                <span className={styles.previewValue}>{selectedInstructor?.name || '—'}</span>
              </div>
              <div className={styles.previewRow}>
                <span className={styles.previewLabel}>الدبلومة</span>
                <span className={styles.previewValue}>{selectedDiploma?.name || '—'}</span>
              </div>
              <div className={styles.previewRow}>
                <span className={styles.previewLabel}>المدة</span>
                <span className={styles.previewValue}>{duration ? `${duration} ساعة` : '—'}</span>
              </div>
              <div className={styles.previewRow}>
                <span className={styles.previewLabel}>الأقسام</span>
                <span className={styles.previewValue}>{selectedSections.length || '—'}</span>
              </div>
            </div>

            {/* Actions */}
            <div className={styles.previewCard}>
              <div className={styles.actions}>
                <button type="submit" className={styles.btnPrimary} disabled={saving}>
                  {saving ? (
                    <>جاري الحفظ...</>
                  ) : (
                    <><Save size={18} /> حفظ التغييرات</>
                  )}
                </button>
              </div>
              <button type="button" className={styles.btnSecondary} onClick={onCancel} disabled={saving} style={{ width: '100%', textAlign: 'center' }}>
                إلغاء
              </button>
            </div>
          </div>
        </div>
      </form>

      <Toast message={toastMessage} type={toastType} isVisible={toastVisible} onClose={() => setToastVisible(false)} />
    </div>
  );
}

'use client';

import React, { useState, useEffect, Suspense, useRef, useCallback } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import Toast from '@/components/Toast';
import { createCourse } from '@/utils/courseService';
import { getAdminCategories, type Diploma } from '@/utils/categoryService';
import { getAdminSections, type Section } from '@/utils/sectionService';
import { getInstructors, type Instructor } from '@/utils/instructorService';
import styles from './NewCourse.module.css';
import '@/styles/toast.css';

type CourseFormData = {
  title: string;
  description: string;
  instructor_id: string;
  category_id: string;
  status: 'draft' | 'published';
  duration: string;
  price: string;
  is_free: boolean;
  cover_image: File | null;
  rank: string;
  section_ids: string[];
};

type FormErrors = Partial<Record<'title' | 'description' | 'instructor_id' | 'category_id' | 'duration' | 'rank' | 'cover_image', string>>;

const allowedCoverTypes = ['image/jpeg', 'image/png', 'image/webp'];
const maxCoverSize = 20048 * 1024;

function formatFileSize(size: number) {
  if (size < 1024 * 1024) return `${Math.round(size / 1024)} ك.ب`;
  return `${(size / (1024 * 1024)).toFixed(1)} م.ب`;
}

function NewCoursePageComponent() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const diplomaId = searchParams.get('diploma_id');

  const [submitting, setSubmitting] = useState(false);
  const [initialLoading, setInitialLoading] = useState(true);
  const [loadError, setLoadError] = useState('');
  const [diplomas, setDiplomas] = useState<Diploma[]>([]);
  const [instructors, setInstructors] = useState<Instructor[]>([]);
  const [sections, setSections] = useState<Section[]>([]);
  const fileInputRef = useRef<HTMLInputElement | null>(null);

  const [formData, setFormData] = useState<CourseFormData>({
    title: '',
    description: '',
    instructor_id: '',
    category_id: diplomaId || '',
    status: 'published',
    duration: '',
    price: '0',
    is_free: true,
    cover_image: null,
    rank: '',
    section_ids: [],
  });
  const [errors, setErrors] = useState<FormErrors>({});
  const [coverPreview, setCoverPreview] = useState<string | null>(null);

  const [toastVisible, setToastVisible] = useState(false);
  const [toastMessage, setToastMessage] = useState('');
  const [toastType, setToastType] = useState<'success' | 'error' | 'warning' | 'info'>('info');

  const [isInstructorMenuOpen, setInstructorMenuOpen] = useState(false);
  const [instructorSearch, setInstructorSearch] = useState('');
  const dropdownRef = useRef<HTMLDivElement | null>(null);

  const showToast = useCallback((message: string, type: 'success' | 'error' | 'warning' | 'info' = 'info') => {
    setToastMessage(message);
    setToastType(type);
    setToastVisible(true);
  }, []);

  const fetchInitialData = useCallback(async () => {
    setInitialLoading(true);
    setLoadError('');
    try {
      const [diplomasData, instructorsData, sectionsData] = await Promise.all([
        getAdminCategories(),
        getInstructors(),
        getAdminSections(),
      ]);
      setDiplomas(diplomasData);
      setSections(sectionsData);
      setInstructors([...instructorsData].sort((a, b) => a.name.localeCompare(b.name, 'ar')));
    } catch (error: unknown) {
      const message = error instanceof Error ? error.message : '';
      const readableMessage = message.includes('401') || message.includes('403')
        ? 'يرجى تسجيل الدخول أولًا قبل إضافة مقرر جديد.'
        : 'تعذر تحميل بيانات الدبلومات أو المحاضرين أو الأقسام.';
      setLoadError(readableMessage);
      showToast(readableMessage, 'error');
    } finally {
      setInitialLoading(false);
    }
  }, [showToast]);

  useEffect(() => {
    fetchInitialData();
  }, [fetchInitialData]);

  useEffect(() => {
    if (diplomaId) {
      setFormData(prev => ({ ...prev, category_id: diplomaId }));
    }
  }, [diplomaId]);

  useEffect(() => {
    function handleClickOutside(e: MouseEvent) {
      if (dropdownRef.current && !dropdownRef.current.contains(e.target as Node)) {
        setInstructorMenuOpen(false);
      }
    }
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    return () => {
      if (coverPreview) URL.revokeObjectURL(coverPreview);
    };
  }, [coverPreview]);

  const selectedDiploma = diplomas.find(d => String(d.id) === formData.category_id);
  const selectedSections = sections.filter(section => formData.section_ids.includes(String(section.id)));
  const selectedInstructor = instructors.find(i => String(i.id) === formData.instructor_id);
  const filteredInstructors = instructors.filter(i => {
    const q = instructorSearch.trim();
    if (!q) return true;
    const s = `${i.name || ''} ${i.title || ''}`;
    return s.includes(q);
  });

  const clearError = (name: keyof FormErrors) => {
    setErrors(prev => {
      if (!prev[name]) return prev;
      const next = { ...prev };
      delete next[name];
      return next;
    });
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target;
    const fieldName = name as keyof FormErrors;
    clearError(fieldName);

    if (type === 'checkbox') {
      const { checked } = e.target as HTMLInputElement;
      setFormData(prev => ({
        ...prev,
        [name]: checked,
        ...(name === 'is_free' && checked && { price: '0' }),
      }));
      return;
    }

    setFormData(prev => ({
      ...prev,
      [name]: value,
    }));
  };

  const handleSelectInstructor = (instructor: Instructor) => {
    setFormData(prev => ({ ...prev, instructor_id: String(instructor.id) }));
    clearError('instructor_id');
    setInstructorMenuOpen(false);
  };

  const validateCoverFile = (file: File) => {
    if (!allowedCoverTypes.includes(file.type)) {
      return 'صيغة صورة الغلاف غير مدعومة. الصيغ المسموحة: JPG, PNG, WebP.';
    }
    if (file.size > maxCoverSize) {
      return 'حجم صورة الغلاف أكبر من المسموح. الحد الأقصى حوالي 20MB.';
    }
    return '';
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0] || null;
    clearError('cover_image');

    if (!file) {
      setFormData(prev => ({ ...prev, cover_image: null }));
      setCoverPreview(null);
      return;
    }

    const fileError = validateCoverFile(file);
    if (fileError) {
      setErrors(prev => ({ ...prev, cover_image: fileError }));
      setFormData(prev => ({ ...prev, cover_image: null }));
      setCoverPreview(null);
      if (fileInputRef.current) fileInputRef.current.value = '';
      return;
    }

    if (coverPreview) URL.revokeObjectURL(coverPreview);
    setFormData(prev => ({ ...prev, cover_image: file }));
    setCoverPreview(URL.createObjectURL(file));
  };

  const triggerFileEdit = () => {
    fileInputRef.current?.click();
  };

  const clearCoverImage = () => {
    setFormData(prev => ({ ...prev, cover_image: null }));
    setCoverPreview(null);
    clearError('cover_image');
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const toggleSection = (sectionId: number) => {
    const id = String(sectionId);
    setFormData(prev => ({
      ...prev,
      section_ids: prev.section_ids.includes(id)
        ? prev.section_ids.filter(item => item !== id)
        : [...prev.section_ids, id],
    }));
  };

  const clearSections = () => {
    setFormData(prev => ({ ...prev, section_ids: [] }));
  };

  const validateForm = () => {
    const nextErrors: FormErrors = {};
    const durationNumber = Number(formData.duration);
    const rankNumber = Number(formData.rank);

    if (!formData.title.trim()) nextErrors.title = 'عنوان المقرر مطلوب.';
    if (!formData.description.trim()) nextErrors.description = 'وصف المقرر مطلوب.';
    if (!formData.instructor_id) nextErrors.instructor_id = 'يرجى اختيار المحاضر.';
    if (!formData.category_id) nextErrors.category_id = 'يرجى اختيار الدبلومة.';
    if (!formData.duration || !Number.isInteger(durationNumber) || durationNumber < 1) {
      nextErrors.duration = 'المدة يجب أن تكون رقمًا صحيحًا أكبر من صفر.';
    }
    if (formData.rank.trim() && (!Number.isInteger(rankNumber) || rankNumber < 1)) {
      nextErrors.rank = 'الترتيب يجب أن يكون رقمًا صحيحًا موجبًا.';
    }
    if (formData.cover_image) {
      const fileError = validateCoverFile(formData.cover_image);
      if (fileError) nextErrors.cover_image = fileError;
    }

    setErrors(nextErrors);
    return Object.keys(nextErrors).length === 0;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (submitting) return;

    if (!validateForm()) {
      showToast('يرجى مراجعة الحقول المطلوبة قبل إنشاء المقرر.', 'error');
      return;
    }

    setSubmitting(true);

    try {
      const formDataToSend = new FormData();
      formDataToSend.append('title', formData.title.trim());
      formDataToSend.append('description', formData.description.trim());
      formDataToSend.append('instructor_id', formData.instructor_id);
      formDataToSend.append('category_id', formData.category_id);
      formDataToSend.append('is_published', formData.status === 'published' ? '1' : '0');
      formDataToSend.append('duration', String(Number(formData.duration)));
      formDataToSend.append('price', '0');
      formDataToSend.append('is_free', '1');
      if (formData.rank.trim()) {
        formDataToSend.append('rank', String(Number(formData.rank)));
      }
      if (formData.section_ids.length > 0) {
        formDataToSend.append('section_id', formData.section_ids[0]);
        formDataToSend.append('section_ids', JSON.stringify(formData.section_ids.map(Number)));
      }
      if (formData.cover_image) {
        formDataToSend.append('cover_image', formData.cover_image);
      }

      await createCourse(formDataToSend);
      showToast('تم إنشاء المقرر بنجاح!', 'success');

      setTimeout(() => {
        if (diplomaId) {
          router.push(`/admin/diplomas/${diplomaId}`);
        } else {
          router.push('/admin/courses');
        }
      }, 1200);
    } catch (error: unknown) {
      showToast(error instanceof Error ? error.message : 'حدث خطأ أثناء إنشاء المقرر', 'error');
    } finally {
      setSubmitting(false);
    }
  };

  const handleBack = () => {
    if (diplomaId) {
      router.push(`/admin/diplomas/${diplomaId}`);
    } else {
      router.push('/admin/diplomas');
    }
  };

  const statusLabel = formData.status === 'published' ? 'منشور' : 'مسودة';
  const diplomaContext = selectedDiploma?.name || (diplomaId ? `رقم ${diplomaId}` : 'غير محددة');

  if (initialLoading) {
    return (
      <div className={styles.container}>
        <div className={styles.header}>
          <div>
            <h1 className={styles.title}>إضافة مقرر جديد</h1>
            <p className={styles.subtitle}>جاري تجهيز بيانات النموذج...</p>
