                        <div className="form-group" style={{ marginTop: 8 }}>
                          <label className="form-label">
                            <input
                              type="radio"
                              name="correctAnswer"
                              checked={questionForm.correctIndex === idx}
                              onChange={() => setQuestionForm({ ...questionForm, correctIndex: idx })}
                            />
                            <span style={{ marginInlineStart: 8 }}>الإجابة الصحيحة</span>
                          </label>
                        </div>
                      </div>
                    ))}

                    <div className="form-group form-grid-full">
                      <label className="form-label">شرح (اختياري)</label>
                      <textarea
                        className="form-textarea"
                        rows={3}
                        value={questionForm.explanation || ''}
                        onChange={(e) => setQuestionForm({ ...questionForm, explanation: e.target.value })}
                        placeholder="اكتب شرحًا مختصرًا إن رغبت"
                      />
                    </div>
                  </div>
                </div>

                <div className="form-actions">
                  <button className="btn-primary" onClick={handleSaveQuestion} disabled={questionSaving}>
                    {questionSaving ? 'جاري الحفظ...' : 'تم'}
                  </button>
                  <button className="btn-secondary" onClick={closeQuestionPopup} disabled={questionSaving}>إلغاء</button>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* --- Toast --- */}
        {toastVisible && (
          <Toast
            isVisible={toastVisible}
            message={toastMessage}
            type={toastType}
            onClose={() => setToastVisible(false)}
          />

        )}
      </div>
    </div>
  );
}

"use client";

import React, { useCallback, useEffect, useMemo, useState } from "react";
import { useParams, useRouter } from "next/navigation";
import { FolderKanban, MoreVertical, Eye, Edit, Trash2 } from "lucide-react";
import Toast from "@/components/Toast";
import styles from "./AdminDiplomaCourses.module.css";
import "@/styles/toast.css";
import { deleteCategory, getAdminCategory, type Diploma } from "@/utils/categoryService";
import { deleteCourse, getAllCourses, getCourses, type Course } from "@/utils/courseService";
import { getBackendAssetUrl } from "@/utils/url";

type StatusFilter = "all" | "published" | "draft";
type PriceFilter = "all" | "free" | "paid";
type SortOption = "rank" | "newest" | "oldest" | "name" | "chapters";
type DeleteTarget = { type: "diploma" } | { type: "course"; course: Course } | null;

const PAGE_SIZE_OPTIONS = [10, 25, 50];

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

function getErrorMessage(error: unknown, fallback: string) {
  if (error instanceof Error && error.message) return error.message;
  if (isObject(error) && typeof error.message === "string") return error.message;
  return fallback;
}

function isCoursePublished(course: Course): boolean {
  if (typeof course.is_published === "boolean") return course.is_published;
  if (typeof course.status === "string") {
    const status = course.status.toLowerCase();
    return status === "published" || status === "1" || status === "true";
  }
  return false;
}

function getStatusText(published: boolean): string {
  return published ? "منشور" : "مسودة";
}

function getCourseStatusValue(course: Course): "published" | "draft" {
  return isCoursePublished(course) ? "published" : "draft";
}

function formatPrice(price: number, isFree?: boolean) {
  if (isFree || price === 0) return "مجاني";
  return `${price.toLocaleString("ar-EG")} ر.س`;
}

function formatDate(value?: string) {
  if (!value) return "غير متاح";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "غير متاح";
  return new Intl.DateTimeFormat("ar-EG", { year: "numeric", month: "short", day: "numeric" }).format(date);
}

function getCourseCategoryId(course: Course): number {
  const extra = course as Course & { categoryId?: number | string };
  return Number(course.category_id ?? course.category?.id ?? extra.categoryId ?? 0);
}

function getCourseSections(course: Course) {
  if (course.sections && course.sections.length > 0) return course.sections;
  return course.section ? [course.section] : [];
}

function getCourseCoverUrl(course: Course) {
  const extra = course as Course & { cover_image_url?: string | null };
  return getBackendAssetUrl(extra.cover_image_url ?? course.cover_image);
}

function getChaptersCount(course: Course) {
  return Number(course.chapters_count ?? course.stats?.chapters_count ?? course.chapters?.length ?? 0);
}

function getLessonsCount(course: Course) {
  const chapterLessons = course.chapters?.reduce((total, chapter) => total + Number(chapter.lessons?.length ?? 0), 0);
  return Number(course.lessons_count ?? course.stats?.lessons_count ?? chapterLessons ?? 0);
}

function courseMatchesDiploma(course: Course, diplomaId: number) {
  return getCourseCategoryId(course) === diplomaId;
}

export default function AdminDiplomaPage() {
  const { id } = useParams() as { id: string };
  const diplomaId = Number(id);
  const router = useRouter();

  const [diploma, setDiploma] = useState<Diploma | null>(null);
  const [courses, setCourses] = useState<Course[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [isDescriptionExpanded, setDescriptionExpanded] = useState(false);
  const [deleteTarget, setDeleteTarget] = useState<DeleteTarget>(null);
  const [isDeleting, setIsDeleting] = useState(false);
  const [openMenuCourseId, setOpenMenuCourseId] = useState<number | null>(null);

  const [searchQuery, setSearchQuery] = useState("");
  const [statusFilter, setStatusFilter] = useState<StatusFilter>("all");
  const [priceFilter, setPriceFilter] = useState<PriceFilter>("all");
  const [sectionFilter, setSectionFilter] = useState("all");
  const [sortOption, setSortOption] = useState<SortOption>("rank");
  const [page, setPage] = useState(1);
  const [perPage, setPerPage] = useState(10);

  const [toastVisible, setToastVisible] = useState(false);
  const [toastMessage, setToastMessage] = useState("");
  const [toastType, setToastType] = useState<"success" | "error" | "warning" | "info">("info");

  const showToast = useCallback((message: string, type: "success" | "error" | "warning" | "info" = "info") => {
    setToastMessage(message);
    setToastType(type);
    setToastVisible(true);
  }, []);

  const fetchData = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);

      const dip = await getAdminCategory(diplomaId);
      setDiploma(dip);

      const adminCourses = await getCourses();
      const filteredAdmin = adminCourses.filter((course) => courseMatchesDiploma(course, diplomaId));

      if (filteredAdmin.length > 0) {
        setCourses(filteredAdmin);
      } else {
        const publicCourses = await getAllCourses({ per_page: 200 });
        setCourses(publicCourses.filter((course) => courseMatchesDiploma(course, diplomaId)));
      }
    } catch (err: unknown) {
      const message = getErrorMessage(err, "حدث خطأ في تحميل بيانات الدبلومة");
      setError(message);
      showToast(message, "error");
    } finally {
      setLoading(false);
    }
  }, [diplomaId, showToast]);

  useEffect(() => {
    if (!Number.isNaN(diplomaId) && diplomaId > 0) {
      fetchData();
    } else {
      setError("معرف دبلومة غير صالح");
      setLoading(false);
    }
  }, [diplomaId, fetchData]);

  useEffect(() => {
    setPage(1);
  }, [searchQuery, statusFilter, priceFilter, sectionFilter, sortOption, perPage]);

  const availableSections = useMemo(() => {
    const map = new Map<number, { id: number; name: string }>();
    courses.forEach((course) => {
      getCourseSections(course).forEach((section) => {
        map.set(section.id, { id: section.id, name: section.name });
      });
    });
    return Array.from(map.values()).sort((a, b) => a.name.localeCompare(b.name, "ar"));
  }, [courses]);

  const coursesStats = useMemo(() => {
    const chapters = courses.reduce((total, course) => total + getChaptersCount(course), 0);
    const lessons = courses.reduce((total, course) => total + getLessonsCount(course), 0);
    const students = courses.reduce((total, course) => total + Number(course.students_count ?? 0), 0);
    return { chapters, lessons, students };
  }, [courses]);

  const filteredCourses = useMemo(() => {
    const query = searchQuery.trim().toLowerCase();
    return courses
      .filter((course) => {
        if (!query) return true;
        return (
          course.title?.toLowerCase().includes(query) ||
          course.instructor?.name?.toLowerCase().includes(query) ||
          course.description?.toLowerCase().includes(query)
        );
      })
      .filter((course) => statusFilter === "all" || getCourseStatusValue(course) === statusFilter)
      .filter((course) => {
        if (priceFilter === "all") return true;
        const isFree = Boolean(course.is_free) || Number(course.price ?? 0) === 0;
        return priceFilter === "free" ? isFree : !isFree;
      })
      .filter((course) => {
        if (sectionFilter === "all") return true;
        return getCourseSections(course).some((section) => String(section.id) === sectionFilter);
      })
      .sort((a, b) => {
        if (sortOption === "name") return (a.title || "").localeCompare(b.title || "", "ar");
        if (sortOption === "chapters") return getChaptersCount(b) - getChaptersCount(a);
        if (sortOption === "oldest") return new Date(a.created_at || 0).getTime() - new Date(b.created_at || 0).getTime();
        if (sortOption === "newest") return new Date(b.created_at || 0).getTime() - new Date(a.created_at || 0).getTime();
        return Number(a.rank ?? Number.MAX_SAFE_INTEGER) - Number(b.rank ?? Number.MAX_SAFE_INTEGER) || Number(a.id) - Number(b.id);
      });
  }, [courses, priceFilter, searchQuery, sectionFilter, sortOption, statusFilter]);

  const totalPages = Math.max(1, Math.ceil(filteredCourses.length / perPage));
  const safePage = Math.min(page, totalPages);
  const pageStart = filteredCourses.length === 0 ? 0 : (safePage - 1) * perPage + 1;
  const pageEnd = Math.min(safePage * perPage, filteredCourses.length);
  const paginatedCourses = filteredCourses.slice((safePage - 1) * perPage, safePage * perPage);

  const hasActiveFilters = Boolean(searchQuery.trim()) || statusFilter !== "all" || priceFilter !== "all" || sectionFilter !== "all" || sortOption !== "rank";

  const resetFilters = () => {
    setSearchQuery("");
    setStatusFilter("all");
    setPriceFilter("all");
    setSectionFilter("all");
    setSortOption("rank");
  };

  const handleAddCourse = () => router.push(`/admin/courses/new?diploma_id=${diplomaId}`);
  const goBack = () => router.push("/admin/diplomas");

  const openDeleteDiploma = () => setDeleteTarget({ type: "diploma" });
  const openDeleteCourse = (course: Course) => {
    setOpenMenuCourseId(null);
    setDeleteTarget({ type: "course", course });
  };

  const performDelete = async () => {
    if (!deleteTarget) return;
    try {
      setIsDeleting(true);
      if (deleteTarget.type === "diploma") {
        await deleteCategory(diplomaId);
        showToast("تم حذف الدبلومة بنجاح", "success");
        router.push("/admin/diplomas");
      } else {
        await deleteCourse(Number(deleteTarget.course.id));
        setCourses((prev) => prev.filter((course) => Number(course.id) !== Number(deleteTarget.course.id)));
        showToast("تم حذف المقرر بنجاح", "success");
        setDeleteTarget(null);
      }
    } catch (err: unknown) {
      const message = getErrorMessage(err, deleteTarget.type === "diploma" ? "فشل في حذف الدبلومة" : "فشل في حذف المقرر");
      showToast(message, "error");
    } finally {
      setIsDeleting(false);
    }
  };

  if (loading) {
    return (
      <div className={styles.container}>
        <div className={styles.skeletonHeader} />
        <div className={styles.skeletonGrid}>
          <span />
          <span />
          <span />
        </div>
        <div className={styles.skeletonPanel}>
          {Array.from({ length: 5 }).map((_, index) => <span key={index} />)}
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className={styles.container}>
        <div className={styles.stateCard}>
          <h2>تعذر تحميل تفاصيل الدبلومة</h2>
          <p>{error}</p>
          <div className={styles.stateActions}>
            <button className={styles.btnPrimary} onClick={fetchData}>إعادة المحاولة</button>
            <button className={styles.btnAction} onClick={goBack}>الرجوع للدبلومات</button>
          </div>
        </div>
        <Toast message={toastMessage} type={toastType} isVisible={toastVisible} onClose={() => setToastVisible(false)} />
      </div>
    );
  }

  if (!diploma) {
    return (
      <div className={styles.container}>
        <div className={styles.stateCard}>
          <h2>لم يتم العثور على الدبلومة المطلوبة.</h2>
          <button className={styles.btnPrimary} onClick={goBack}>الرجوع للدبلومات</button>
        </div>
      </div>
    );
  }

  const diplomaPublished = Boolean(diploma.is_published);
  const diplomaPrice = formatPrice(Number(diploma.price ?? 0), Boolean(diploma.is_free));
  const studentsCount = typeof diploma.students_count === "number" ? diploma.students_count : null;
  const description = diploma.description || "غير متاح";
  const shouldShowDescriptionToggle = description.length > 240;

  return (
    <div className={styles.container}>
      <header className={styles.header}>
        <div className={styles.titleContainer}>
          <div className={styles.headerText}>
            <span className={styles.headerEyebrow}>تفاصيل دبلومة</span>
            <div className={styles.titleLine}>
              <h1 className={styles.title}>دبلومة: {diploma.name}</h1>
              <span className={diplomaPublished ? styles.statusPublished : styles.statusDraft}>{getStatusText(diplomaPublished)}</span>
            </div>
            <p className={styles.subtitle}>
              {courses.length.toLocaleString("ar-EG")} مقرر • {diplomaPrice} • آخر تحديث: {formatDate(diploma.updated_at)}
            </p>
          </div>
          <button className={styles.backButton} onClick={goBack}>الرجوع للدبلومات</button>
        </div>
      </header>

      <section className={styles.diplomaOverview}>
        <article className={styles.diplomaCard}>
          <div className={styles.diplomaCardHeader}>
            <div>
              <span className={styles.cardLabel}>بيانات الدبلومة</span>
              <h2>{diploma.name}</h2>
            </div>
            <span className={diplomaPublished ? styles.statusPublished : styles.statusDraft}>{getStatusText(diplomaPublished)}</span>
          </div>

          <p className={`${styles.description} ${isDescriptionExpanded ? styles.descriptionExpanded : ""}`}>
            {description}
          </p>
          {shouldShowDescriptionToggle && (
            <button type="button" className={styles.textButton} onClick={() => setDescriptionExpanded((value) => !value)}>
              {isDescriptionExpanded ? "عرض أقل" : "عرض المزيد"}
            </button>
          )}

          <dl className={styles.infoGrid}>
            <div>
              <dt>المعرف</dt>
              <dd>{diploma.id}</dd>
            </div>
            <div>
              <dt>السعر</dt>
              <dd>{diplomaPrice}</dd>
            </div>
            <div>
              <dt>عدد المقررات</dt>
              <dd>{courses.length.toLocaleString("ar-EG")}</dd>
            </div>
            <div>
              <dt>عدد الطلاب</dt>
              <dd>{studentsCount !== null ? studentsCount.toLocaleString("ar-EG") : "غير متاح"}</dd>
            </div>
            <div>
              <dt>آخر تحديث</dt>
              <dd>{formatDate(diploma.updated_at)}</dd>
            </div>
          </dl>
        </article>

        <aside className={styles.actionsPanel}>
          <span className={styles.cardLabel}>إجراءات الدبلومة</span>
          <button className={styles.btnPrimary} onClick={handleAddCourse}>إضافة مقرر جديد</button>
          <button className={styles.btnAction} onClick={() => router.push(`/admin/diplomas/${diplomaId}/students`)}>
            خريجو الدبلومة
          </button>
          <button className={styles.btnDangerSubtle} onClick={openDeleteDiploma} disabled={isDeleting}>
            حذف الدبلومة
          </button>
        </aside>
      </section>

      <section className={styles.statsGrid}>
        <div className={styles.statCard}>
          <span>المقررات</span>
          <strong>{courses.length.toLocaleString("ar-EG")}</strong>
        </div>
        <div className={styles.statCard}>
          <span>الفصول</span>
          <strong>{coursesStats.chapters.toLocaleString("ar-EG")}</strong>
        </div>
        <div className={styles.statCard}>
          <span>الدروس</span>
          <strong>{coursesStats.lessons.toLocaleString("ar-EG")}</strong>
        </div>
        <div className={styles.statCard}>
          <span>الطلاب</span>
          <strong>{studentsCount !== null ? studentsCount.toLocaleString("ar-EG") : "غير متاح"}</strong>
        </div>
        <div className={styles.statCard}>
          <span>الحالة</span>
          <strong>{getStatusText(diplomaPublished)}</strong>
        </div>
        <div className={styles.statCard}>
          <span>السعر</span>
          <strong>{diplomaPrice}</strong>
        </div>
      </section>

      <section className={styles.list}>
        <div className={styles.listHeader}>
          <div>
            <h2 className={styles.sectionTitle}>مقررات الدبلومة</h2>
            <p>إدارة المقررات المرتبطة بهذه الدبلومة وفصولها ومحتواها.</p>
          </div>
          <button className={styles.btnPrimary} onClick={handleAddCourse}>إضافة مقرر جديد</button>
        </div>

        {courses.length > 0 ? (
          <>
            <div className={styles.filtersBar}>
              <div className={styles.searchField}>
                <input
                  type="text"
                  placeholder="ابحث باسم المقرر أو المدرب"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                />
                {searchQuery && <button type="button" onClick={() => setSearchQuery("")}>×</button>}
              </div>
              <label>
                الحالة
                <select value={statusFilter} onChange={(e) => setStatusFilter(e.target.value as StatusFilter)}>
                  <option value="all">الكل</option>
                  <option value="published">منشور</option>
                  <option value="draft">مسودة</option>
                </select>
              </label>
              <label>
                السعر
                <select value={priceFilter} onChange={(e) => setPriceFilter(e.target.value as PriceFilter)}>
                  <option value="all">الكل</option>
                  <option value="free">مجاني</option>
                  <option value="paid">مدفوع</option>
                </select>
              </label>
              <label>
                القسم
                <select value={sectionFilter} onChange={(e) => setSectionFilter(e.target.value)}>
                  <option value="all">الكل</option>
                  {availableSections.map((section) => (
                    <option key={section.id} value={section.id}>{section.name}</option>
                  ))}
                </select>
              </label>
              <label>
                الترتيب
                <select value={sortOption} onChange={(e) => setSortOption(e.target.value as SortOption)}>
                  <option value="rank">حسب الترتيب</option>
                  <option value="newest">الأحدث</option>
                  <option value="oldest">الأقدم</option>
                  <option value="name">الاسم أ-ي</option>
                  <option value="chapters">الأكثر فصولًا</option>
                </select>
              </label>
              <button className={styles.btnReset} onClick={resetFilters} disabled={!hasActiveFilters}>إعادة ضبط الفلاتر</button>
            </div>

            {filteredCourses.length === 0 ? (
              <div className={styles.emptyState}>
                <h3>لا توجد مقررات مطابقة للفلاتر الحالية.</h3>
                <button className={styles.btnPrimary} onClick={resetFilters}>إعادة ضبط الفلاتر</button>
              </div>
            ) : (
              <>
                <div className={styles.tableContainer}>
                  <table className={styles.table}>
                    <thead>
                      <tr>
                        <th>المقرر</th>
                        <th>الحالة</th>
                        <th>السعر</th>
                        <th>المحتوى</th>
                        <th>الإجراءات</th>
                      </tr>
                    </thead>
                    <tbody>
                      {paginatedCourses.map((course) => {
                        const published = isCoursePublished(course);
                        const coverUrl = getCourseCoverUrl(course);
                        const courseSections = getCourseSections(course);
                        const chaptersCount = getChaptersCount(course);
                        const lessonsCount = getLessonsCount(course);
                        const courseId = Number(course.id);
                        return (
                          <tr key={String(course.id)}>
                            <td>
                              <div className={styles.courseCell}>
                                {coverUrl ? (
                                  <img className={styles.coverThumb} src={coverUrl} alt={course.title} />
                                ) : (
                                  <div className={styles.coverThumbPlaceholder}>بدون صورة</div>
                                )}
                                <div className={styles.courseInfo}>
                                  <strong>{course.title}</strong>
                                  <span>{course.instructor?.name || "المدرب غير متاح"}</span>
                                  <small>{courseSections.length > 0 ? courseSections.map((section) => section.name).join("، ") : "غير مصنف"}</small>
                                </div>
                              </div>
                            </td>
                            <td>
                              <span className={published ? styles.statusPublished : styles.statusDraft}>{getStatusText(published)}</span>
                            </td>
                            <td>
                              <span className={Boolean(course.is_free) || Number(course.price ?? 0) === 0 ? styles.priceFree : styles.pricePaid}>
                                {formatPrice(Number(course.price ?? 0), Boolean(course.is_free))}
                              </span>
                            </td>
                            <td>
                              <div className={styles.contentCell}>
                                <strong>{chaptersCount.toLocaleString("ar-EG")} فصل</strong>
                                <span>{lessonsCount > 0 ? `${lessonsCount.toLocaleString("ar-EG")} درس` : "الدروس غير متاحة"}</span>
                              </div>
                            </td>
                            <td className={styles.actionsCell}>
                              <button
                                className={styles.btnAction}
                                title="إدارة المحتوى"
                                onClick={() => router.push(`/admin/diplomas/${diplomaId}/courses/${course.id}/chapters`)}
                              >
                                <FolderKanban size={18} />
                              </button>
                              <button
                                className={styles.btnAction}
                                title="عرض"
                                onClick={() => window.open(`/course-details/${course.id}`, '_blank')}
                              >
                                <Eye size={18} />
                              </button>
                              <button
                                className={styles.btnAction}
                                title="تعديل"
                                onClick={() => router.push(`/admin/courses/${course.id}`)}
                              >
                                <Edit size={18} />
                              </button>
                              <button
                                className={styles.btnAction}
                                style={{ color: '#ef4444', backgroundColor: '#fee2e2' }}
                                title="حذف"
                                onClick={() => openDeleteCourse(course)}
                              >
                                <Trash2 size={18} />
                              </button>
                            </td>
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
                </div>

                <div className={styles.pagination}>
                  <span>عرض {pageStart.toLocaleString("ar-EG")} إلى {pageEnd.toLocaleString("ar-EG")} من أصل {filteredCourses.length.toLocaleString("ar-EG")} مقررًا</span>
                  <label>
                    عدد العناصر
                    <select value={perPage} onChange={(e) => setPerPage(Number(e.target.value))}>
                      {PAGE_SIZE_OPTIONS.map((option) => <option key={option} value={option}>{option}</option>)}
                    </select>
                  </label>
                  <div>
                    <button disabled={safePage <= 1} onClick={() => setPage((value) => Math.max(1, value - 1))}>السابق</button>
                    <strong>صفحة {safePage.toLocaleString("ar-EG")} من {totalPages.toLocaleString("ar-EG")}</strong>
                    <button disabled={safePage >= totalPages} onClick={() => setPage((value) => Math.min(totalPages, value + 1))}>التالي</button>
                  </div>
                </div>
              </>
            )}
          </>
        ) : (
          <div className={styles.emptyState}>
            <h3>لا توجد مقررات في هذه الدبلومة بعد.</h3>
            <p>ابدأ بإضافة أول مقرر لهذه الدبلومة حتى يظهر للطلاب حسب إعدادات النشر.</p>
            <button className={styles.btnPrimary} onClick={handleAddCourse}>إضافة أول مقرر</button>
          </div>
        )}
      </section>

      {deleteTarget && (
        <div className={styles.modalOverlay} role="dialog" aria-modal="true">
          <div className={styles.confirmModal}>
            <h2>{deleteTarget.type === "diploma" ? "حذف الدبلومة" : "حذف المقرر"}</h2>
            <p>
              {deleteTarget.type === "diploma"
                ? "هل أنت متأكد من حذف هذه الدبلومة؟ قد يؤثر ذلك على المقررات والطلاب المرتبطين بها."
                : `هل أنت متأكد من حذف المقرر "${deleteTarget.course.title}"؟ قد يتم حذف أو تعطيل الفصول المرتبطة به حسب إعدادات النظام.`}
            </p>
            <div className={styles.modalActions}>
              <button className={styles.btnAction} onClick={() => setDeleteTarget(null)} disabled={isDeleting}>إلغاء</button>
              <button className={styles.btnDanger} onClick={performDelete} disabled={isDeleting}>
                {isDeleting ? "جاري الحذف..." : deleteTarget.type === "diploma" ? "حذف الدبلومة" : "حذف المقرر"}
              </button>
            </div>
          </div>
        </div>
      )}

      <Toast message={toastMessage} type={toastType} isVisible={toastVisible} onClose={() => setToastVisible(false)} />
    </div>
  );
}

'use client';

import React, { useEffect, useMemo, useState } from 'react';
import { useParams } from 'next/navigation';
import styles from './AdminQuestionBank.module.css';
import { getOrCreateDiplomaFinalExam } from '@/utils/quizService';
import { createQuestion, deleteQuestion, getQuizQuestions, Question, QuestionData, updateQuestion } from '@/utils/questionService';
import { getAdminCategory, type Diploma } from '@/utils/categoryService';
import Toast from '@/components/Toast';

interface EditableQuestion {
  id: number; // < 0 يعني مؤقت/جديد
  text: string;
  options: string[];
  correctAnswer: number;
  explanation?: string;
  isNew?: boolean;
  isDirty?: boolean;
  collapsed?: boolean;
}

// تحديث جلب المعرف لدعم كلٍ من [id] و [diplomaId]
const useDiplomaId = (): number => {
  const params = useParams() as { id?: string; diplomaId?: string };
  return useMemo(() => Number(params?.id ?? params?.diplomaId ?? 0), [params]);
};

export default function DiplomaQuestionBankPage() {
  const diplomaId = useDiplomaId();
  const [quizId, setQuizId] = useState<number | null>(null);
  const [questions, setQuestions] = useState<EditableQuestion[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [savingAll, setSavingAll] = useState<boolean>(false);
  const [diploma, setDiploma] = useState<Diploma | null>(null);

  // Toast state
  const [toastVisible, setToastVisible] = useState(false);
  const [toastMessage, setToastMessage] = useState('');
  const [toastType, setToastType] = useState<'success' | 'error' | 'warning' | 'info' | 'confirm'>('info');

  // جلب اسم الدبلومة لعرضه في العنوان
  useEffect(() => {
    if (!diplomaId) return;
    getAdminCategory(diplomaId)
      .then(setDiploma)
      .catch(() => { /* تجاهل الخطأ ولا نمنع تهيئة بنك الأسئلة */ });
  }, [diplomaId]);

  useEffect(() => {
    const init = async () => {
      if (!diplomaId) { setLoading(false); return; }
      setLoading(true);
      showToast('جاري تحميل بنك الأسئلة...', 'info');
      try {
        const exam = await getOrCreateDiplomaFinalExam(diplomaId, 'امتحان نهائي الدبلومة');
        const qId = Number(exam?.id);
        setQuizId(qId);
        const qs = await getQuizQuestions(qId);
        const mapped: EditableQuestion[] = (qs || []).map(mapToEditable);
        setQuestions(mapped);
        showToast('تم تحميل بنك الأسئلة بنجاح', 'success');
      } catch (err: any) {
        const msg = err?.message || 'تعذر تهيئة بنك الأسئلة لهذه الدبلومة';
        showToast(msg, 'error');
      } finally {
        setLoading(false);
      }
    };
    init();
  }, [diplomaId]);

  // Toast functions
  const showToast = (message: string, type: 'success' | 'error' | 'warning' | 'info' | 'confirm') => {
    setToastMessage(message);
    setToastType(type);
    setToastVisible(true);
  };

  const closeToast = () => {
    setToastVisible(false);
  };

  const mapToEditable = (q: Question): EditableQuestion => {
    return {
      id: Number(q.id),
      text: String(q.text ?? q.question ?? ''),
      options: Array.isArray(q.options) ? q.options : [],
      correctAnswer: Number(q.correctAnswer ?? 0),
      explanation: q.explanation ?? '',
      isNew: false,
      isDirty: false,
      collapsed: true,
    };
  };

  const addNewQuestion = () => {
    const tempId = -Date.now();
    setQuestions((prev) => [
      ...prev,
      {
        id: tempId,
        text: '',
        options: ['', '', '', ''],
        correctAnswer: 0,
        explanation: '',
        isNew: true,
        isDirty: true,
        collapsed: false,
      },
    ]);
    showToast('تم إضافة سؤال جديد', 'info');
  };

  const markDirty = (id: number, updater: (q: EditableQuestion) => EditableQuestion) => {
    setQuestions((prev) => prev.map((q) => (q.id === id ? { ...updater(q), isDirty: true } : q)));
  };

  const removeOption = (qid: number, index: number) => {
    markDirty(qid, (q) => ({ ...q, options: q.options.filter((_, i) => i !== index) }));
  };

  const addOption = (qid: number) => {
    markDirty(qid, (q) => ({ ...q, options: [...q.options, ''] }));
  };

  const toggleCollapsed = (qid: number) => {
    setQuestions((prev) => prev.map((q) => (q.id === qid ? { ...q, collapsed: !q.collapsed } : q)));
  };

  const saveQuestion = async (q: EditableQuestion) => {
    if (!quizId) return;
    try {
      const payload: QuestionData = {
        text: q.text,
        options: q.options,
        correctAnswer: q.correctAnswer,
        explanation: q.explanation,
      };
      if (q.isNew || q.id < 0) {
        const created = await createQuestion(quizId, payload);
        const updated = mapToEditable(created);
        setQuestions((prev) => prev.map((x) => (x.id === q.id ? updated : x)));
        showToast('تم إنشاء السؤال بنجاح', 'success');
      } else {
        const updatedQ = await updateQuestion(q.id, payload);
        const updated = mapToEditable(updatedQ);
        setQuestions((prev) => prev.map((x) => (x.id === q.id ? updated : x)));
        showToast('تم حفظ التعديلات', 'success');
      }
    } catch (err: any) {
      showToast(err?.message || 'تعذر حفظ السؤال', 'error');
    }
  };

  const deleteQuestionNow = async (qid: number) => {
    if (qid < 0) {
      // لم يُحفَظ بعد؛ فقط احذف من الحالة
      setQuestions((prev) => prev.filter((q) => q.id !== qid));
      showToast('تم حذف السؤال', 'success');
      return;
    }
    try {
      await deleteQuestion(qid);
      setQuestions((prev) => prev.filter((q) => q.id !== qid));
      showToast('تم حذف السؤال', 'success');
    } catch (err: any) {
      showToast(err?.message || 'تعذر حذف السؤال', 'error');
    }
  };

  const saveAll = async () => {
    if (!quizId) return;
    setSavingAll(true);
    showToast('جاري حفظ جميع التغييرات...', 'info');

    try {
      const dirtyQuestions = questions.filter(q => q.isNew || q.isDirty);
      if (dirtyQuestions.length === 0) {
        showToast('لا توجد تغييرات للحفظ', 'warning');
        return;
      }

      for (const q of dirtyQuestions) {
        await saveQuestion(q);
      }
      showToast(`تم حفظ ${dirtyQuestions.length} سؤال بنجاح`, 'success');
    } catch (err: any) {
      showToast(err?.message || 'حدث خطأ أثناء حفظ الكل', 'error');
    } finally {
      setSavingAll(false);
    }
  };

  // Check if there are unsaved changes
  const hasUnsavedChanges = questions.some(q => q.isNew || q.isDirty);

  return (
    <div className={styles.root}>
      <div className={styles.header}>
        <div className={styles.headerContent}>
          <div className={styles.titleSection}>
            <h1 className={styles.title}>بنك أسئلة الدبلومة</h1>
            <p className={styles.subtitle}>{diploma?.name ?? `دبلومة #${diplomaId}`}</p>
          </div>
          <div className={styles.headerActions}>
            <button 
              className={styles.addBtn} 
              onClick={addNewQuestion}
              disabled={loading}
            >
              <span className={styles.btnIcon}>+</span>
              إضافة سؤال جديد
            </button>
            <button 
              className={`${styles.saveAllBtn} ${hasUnsavedChanges ? styles.hasChanges : ''}`} 
              onClick={saveAll} 
              disabled={savingAll || loading || !hasUnsavedChanges}
            >
              {savingAll ? (
                <>
                  <span className={styles.spinner}></span>
                  جاري الحفظ...
                </>
              ) : (
                <>
                  <span className={styles.btnIcon}>💾</span>
                  حفظ كل التغييرات
                  {hasUnsavedChanges && <span className={styles.changesBadge}>{questions.filter(q => q.isNew || q.isDirty).length}</span>}
                </>
              )}
            </button>
          </div>
        </div>
      </div>

      {loading && (
        <div className={styles.loadingContainer}>
          <div className={styles.spinner}></div>
          <p>جاري التحميل...</p>
        </div>
      )}

      {!loading && (
        <div className={styles.questionsContainer}>
          {questions.map((q, idx) => (
            <div className={`${styles.questionCard} ${q.isDirty || q.isNew ? styles.hasChanges : ''}`} key={q.id}>
              <div className={styles.questionHeader}>
                <div className={styles.questionInfo}>
                  <div className={styles.questionNumber}>
                    <span className={styles.questionNumberText}>سؤال #{idx + 1}</span>
                    {q.isNew && <span className={styles.newBadge}>جديد</span>}
                    {q.isDirty && !q.isNew && <span className={styles.modifiedBadge}>معدل</span>}
                  </div>
                </div>
                <div className={styles.questionActions}>
                  <button 
                    className={styles.toggleBtn} 
                    onClick={() => toggleCollapsed(q.id)}
                    title={q.collapsed ? 'فتح السؤال' : 'إغلاق السؤال'}
                  >
                    <span className={`${styles.toggleIcon} ${q.collapsed ? styles.collapsed : ''}`}>▼</span>
                  </button>
                  <button 
                    className={styles.deleteBtn} 
                    onClick={() => deleteQuestionNow(q.id)}
                    title="حذف السؤال"
                  >
                    <span className={styles.deleteIcon}>🗑️</span>
                  </button>
                </div>
              </div>

              {!q.collapsed && (
                <div className={styles.questionContent}>
                  <div className={styles.field}>
                    <label className={styles.fieldLabel}>نص السؤال</label>
                    <textarea
                      className={styles.questionTextarea}
                      value={q.text}
                      onChange={(e) => markDirty(q.id, (x) => ({ ...x, text: e.target.value }))}
                      placeholder="اكتب نص السؤال هنا..."
                    />
                  </div>

                  <div className={styles.field}>
                    <label className={styles.fieldLabel}>الخيارات</label>
                    <div className={styles.optionsContainer}>
                      {q.options.map((opt, i) => (
                        <div className={styles.optionRow} key={i}>
                          <div className={styles.optionRadio}>
                            <input
                              type="radio"
                              name={`correct-${q.id}`}
                              checked={q.correctAnswer === i}
                              onChange={() => markDirty(q.id, (x) => ({ ...x, correctAnswer: i }))}
                              id={`option-${q.id}-${i}`}
                            />
                            <label htmlFor={`option-${q.id}-${i}`} className={styles.radioLabel}>
                              {q.correctAnswer === i ? '✓' : ''}
                            </label>
                          </div>
                          <input
                            className={styles.optionInput}
                            value={opt}
                            onChange={(e) => markDirty(q.id, (x) => {
                              const next = [...x.options];
                              next[i] = e.target.value;
                              return { ...x, options: next };
                            })}
                            placeholder={`الخيار ${i + 1}`}
                          />
                          <button 
                            className={styles.removeOptionBtn} 
                            onClick={() => removeOption(q.id, i)}
                            title="حذف الخيار"
                            disabled={q.options.length <= 2}
                          >
                            <span className={styles.removeIcon}>−</span>
                          </button>
                        </div>
                      ))}
                    </div>
                    <button 
                      className={styles.addOptionBtn} 
                      onClick={() => addOption(q.id)}
                      disabled={q.options.length >= 6}
                    >
                      <span className={styles.addIcon}>+</span>
                      إضافة خيار
                    </button>
                  </div>

                  <div className={styles.field}>
                    <label className={styles.fieldLabel}>توضيح/شرح (اختياري)</label>
                    <textarea
                      className={styles.explanationTextarea}
                      value={q.explanation ?? ''}
                      onChange={(e) => markDirty(q.id, (x) => ({ ...x, explanation: e.target.value }))}
                      placeholder="اكتب شرحاً أو توضيحاً للإجابة الصحيحة..."
                    />
                  </div>
                </div>
              )}
            </div>
          ))}

          {questions.length === 0 && (
            <div className={styles.emptyState}>
              <div className={styles.emptyIcon}>📝</div>
              <h3>لا توجد أسئلة حالياً</h3>
              <p>ابدأ بإضافة أول سؤال لبنك الأسئلة</p>
              <button className={styles.addBtn} onClick={addNewQuestion}>
                <span className={styles.btnIcon}>+</span>
                إضافة سؤال جديد
              </button>
            </div>
          )}
        </div>
      )}

      {/* Toast Component */}
      <Toast
        message={toastMessage}
        type={toastType}
        isVisible={toastVisible}
        onClose={closeToast}
      />
    </div>
  );
}

'use client';

import React, { useEffect, useState } from 'react';
import styles from './Admin.module.css';
import { getAdminCategories } from '../../utils/categoryService';
import { getStudentsStatus, EnrolledDiplomaItem } from '../../utils/studentsService';
import WorldUsersMap from '../../components/WorldUsersMap';
import { getGeneralStats, getStudentsByCountry } from '../../utils/statsService';

export default function AdminDashboard() {
  const [totalDiplomas, setTotalDiplomas] = useState<number>(0);
  const [totalStudents, setTotalStudents] = useState<number>(0);
  const [totalCourses, setTotalCourses] = useState<number>(0);
  const [countriesCount, setCountriesCount] = useState<number>(0);
  const [monthlyRevenue, setMonthlyRevenue] = useState<number>(0);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string>('');

  useEffect(() => {
    const loadStats = async () => {
      setLoading(true);
      try {
        const [general, categories, studentsResp, countries] = await Promise.all([
          getGeneralStats(),
          getAdminCategories(),
          getStudentsStatus(),
          getStudentsByCountry(),
        ]);

        const students = studentsResp?.data ?? [];
        const stats = studentsResp?.stats;

        setTotalDiplomas(categories.length);
        setTotalStudents(general?.total_students ?? stats?.total_students ?? students.length);
        setTotalCourses(general?.total_courses ?? 0);
        setCountriesCount(Array.isArray(countries) ? countries.length : 0);

        const now = new Date();
        const currentMonth = now.getMonth();
        const currentYear = now.getFullYear();

        const enrollments: EnrolledDiplomaItem[] = students.flatMap((s: any) => s.diplomas || []);
        const monthlySum = enrollments.reduce((sum, d) => {
          const enrolledAt = d.enrolled_at ? new Date(d.enrolled_at) : null;
          const sameMonth = enrolledAt
            ? enrolledAt.getMonth() === currentMonth && enrolledAt.getFullYear() === currentYear
            : false;
          const isPaid = !d.is_free && Number(d.price) > 0;
          const isActive = (d.status || '').toLowerCase() === 'active';
          return sameMonth && isPaid && isActive ? sum + Number(d.price) : sum;
        }, 0);

        setMonthlyRevenue(monthlySum);
        setError('');
      } catch (e: any) {
        console.error('Failed to load admin stats', e);
        setError(e?.message || 'تعذر جلب الإحصائيات من الباك ايند');
      } finally {
        setLoading(false);
      }
    };

    loadStats();
  }, []);

  const formatCurrency = (value: number) => {
    try {
      return new Intl.NumberFormat('ar-EG', { maximumFractionDigits: 0 }).format(value) + ' ج.م';
    } catch {
      return `${value} ج.م`;
    }
  };

  return (
    <>
      <div className={styles["dashboard-header"]}>
        <h1>لوحة التحكم الإدارية</h1>
        <p>مرحباً بك في لوحة التحكم الإدارية</p>
      </div>

      {error ? (
        <div className={styles["dashboard-error"]}>{error}</div>
      ) : null}

      <div className={styles["dashboard-stats"]}>
        <div className={styles["stat-card"]}>
          <h3>عدد الطلاب</h3>
          <p className={styles["stat-number"]}>{loading ? '...' : totalStudents}</p>
        </div>
        <div className={styles["stat-card"]}>
          <h3>عدد المقررات</h3>
          <p className={styles["stat-number"]}>{loading ? '...' : totalCourses}</p>
        </div>
        <div className={styles["stat-card"]}>
          <h3>عدد الدبلومات</h3>
          <p className={styles["stat-number"]}>{loading ? '...' : totalDiplomas}</p>
        </div>
        <div className={styles["stat-card"]}>
          <h3>عدد البلاد</h3>
          <p className={styles["stat-number"]}>{loading ? '...' : countriesCount}</p>
        </div>
      </div>

      {/* خريطة المستخدمين حول العالم داخل لوحة التحكم */}
      <div style={{ marginTop: 24 }}>
        <WorldUsersMap />
      </div>

      <div className={styles["quick-actions"]}>
        <h2>الإجراءات السريعة</h2>
        <div className={styles["actions-grid"]}>
          <a href="/admin/diplomas" className={styles["action-card"]}>
            <h3>إدارة الدبلومات</h3>
            <p>إضافة وتعديل الدبلومات</p>
          </a>
          <a href="/admin/students" className={styles["action-card"]}>
            <h3>إدارة الطلاب</h3>
            <p>عرض وإدارة الطلاب المسجلين</p>
          </a>
          {/* <a href="/admin/reports/financial" className="action-card">
            <h3>التقارير</h3>
            <p>عرض تقارير الأداء والإحصائيات</p>
          </a> */}
          <a href="/admin/profile-management" className={styles["action-card"]}>
            <h3>إدارة الملف الشخصي</h3>
            <p>إدارة معلومات المستخدم</p>
          </a>
        </div>
      </div>
    </>
  );
}

'use client';

import React, { useState, useRef } from 'react';
import styles from './PrivacyPolicy.module.css';

const PrivacyPolicyPage: React.FC = () => {
  const [content, setContent] = useState('');
  const [fontSize, setFontSize] = useState(16);
  const [isBold, setIsBold] = useState(false);
  const [isItalic, setIsItalic] = useState(false);
  const [isUnderline, setIsUnderline] = useState(false);
  const [textAlign, setTextAlign] = useState('right');
  const [textColor, setTextColor] = useState('#000000');
  const editorRef = useRef<HTMLDivElement>(null);

  const handleFormatting = (command: string, value?: string) => {
    const selection = window.getSelection();
    if (selection && selection.rangeCount > 0) {
      // إذا كان هناك نص محدد، طبق التنسيق على النص المحدد فقط
      document.execCommand(command, false, value);
    } else {
      // إذا لم يكن هناك نص محدد، طبق التنسيق على النص الجديد
      document.execCommand(command, false, value);
    }
    if (editorRef.current) {
      setContent(editorRef.current.innerHTML);
    }
  };

  const handleFontSizeChange = (size: number) => {
    setFontSize(size);
    const selection = window.getSelection();
    if (selection && selection.toString().length > 0) {
      // تطبيق حجم الخط على النص المحدد فقط
      document.execCommand('fontSize', false, '7');
      const fontElements = document.querySelectorAll('font[size="7"]');
      fontElements.forEach(element => {
        (element as HTMLElement).style.fontSize = `${size}px`;
        element.removeAttribute('size');
      });
    } else {
      handleFormatting('fontSize', size.toString());
    }
  };

  const handleTextAlignChange = (align: string) => {
    setTextAlign(align);
    const selection = window.getSelection();
    if (selection && selection.toString().length > 0) {
      // للنص المحدد، نحتاج لتطبيق المحاذاة على العنصر الأب
      const range = selection.getRangeAt(0);
      const parentElement = range.commonAncestorContainer.nodeType === Node.TEXT_NODE 
        ? range.commonAncestorContainer.parentElement 
        : range.commonAncestorContainer as HTMLElement;

      if (parentElement && editorRef.current?.contains(parentElement)) {
        (parentElement as HTMLElement).style.textAlign = align;
      }
    } else {
      handleFormatting('justify' + align.charAt(0).toUpperCase() + align.slice(1));
    }
  };

  const handleColorChange = (color: string) => {
    setTextColor(color);
    handleFormatting('foreColor', color);
  };

  const applyCustomStyle = (styleName: string) => {
    const selection = window.getSelection();
    if (selection && selection.toString().length > 0) {
      const range = selection.getRangeAt(0);
      const span = document.createElement('span');

      switch (styleName) {
        case 'heading':
          span.style.fontSize = '24px';
          span.style.fontWeight = 'bold';
          span.style.color = '#2c3e50';
          span.style.display = 'block';
          span.style.marginBottom = '15px';
          break;
        case 'subheading':
          span.style.fontSize = '20px';
          span.style.fontWeight = '600';
          span.style.color = '#34495e';
          span.style.display = 'block';
          span.style.marginBottom = '10px';
          break;
        case 'highlight':
          span.style.backgroundColor = '#fff3cd';
          span.style.padding = '2px 6px';
          span.style.borderRadius = '4px';
          span.style.fontWeight = '500';
          break;
        case 'important':
          span.style.color = '#dc3545';
          span.style.fontWeight = 'bold';
          span.style.fontSize = '18px';
          break;
      }

      try {
        range.surroundContents(span);
        selection.removeAllRanges();
      } catch (e) {
        // إذا فشل، استخدم طريقة بديلة
        const contents = range.extractContents();
        span.appendChild(contents);
        range.insertNode(span);
      }

      if (editorRef.current) {
        setContent(editorRef.current.innerHTML);
      }
    }
  };

  const handleSave = () => {
    // هنا يمكن إضافة منطق حفظ المحتوى
    console.log('محتوى سياسة الخصوصية:', content);
    alert('تم حفظ سياسة الخصوصية بنجاح!');
  };

  return (
    <div className={styles["privacyPage"]}>
      <div className="page-header">
        <h1>سياسة الخصوصية</h1>
        <p>إدارة وتحرير سياسة الخصوصية للموقع</p>
      </div>

      <div className="editor-container">
        {/* شريط الأدوات */}
        <div className="toolbar">
          <div className="toolbar-group">
            <button
              className="toolbar-btn"
              onClick={() => applyCustomStyle('heading')}
              title="عنوان رئيسي"
            >
              H1
            </button>
            <button
              className="toolbar-btn"
              onClick={() => applyCustomStyle('subheading')}
              title="عنوان فرعي"
            >
              H2
            </button>
            <button
              className="toolbar-btn"
              onClick={() => applyCustomStyle('highlight')}
              title="تمييز النص"
            >
              🎨
            </button>
            <button
              className="toolbar-btn"
              onClick={() => applyCustomStyle('important')}
              title="نص مهم"
            >
              ⚠️
            </button>
          </div>

          <div className="toolbar-group">
            <button
              className={`toolbar-btn ${isBold ? 'active' : ''}`}
              onClick={() => {
                setIsBold(!isBold);
                handleFormatting('bold');
              }}
              title="عريض"
            >
              <strong>B</strong>
            </button>
            <button
              className={`toolbar-btn ${isItalic ? 'active' : ''}`}
              onClick={() => {
                setIsItalic(!isItalic);
                handleFormatting('italic');
              }}
              title="مائل"
            >
              <em>I</em>
            </button>
            <button
              className={`toolbar-btn ${isUnderline ? 'active' : ''}`}
              onClick={() => {
                setIsUnderline(!isUnderline);
                handleFormatting('underline');
              }}
              title="تحته خط"
            >
              <u>U</u>
            </button>
          </div>

          <div className="toolbar-group">
            <select
              value={fontSize}
              onChange={(e) => handleFontSizeChange(Number(e.target.value))}
              className="font-size-select"
            >
              <option value={12}>12px</option>
              <option value={14}>14px</option>
              <option value={16}>16px</option>
              <option value={18}>18px</option>
              <option value={20}>20px</option>
              <option value={24}>24px</option>
              <option value={28}>28px</option>
              <option value={32}>32px</option>
            </select>
          </div>

          <div className="toolbar-group">
            <button
              className={`toolbar-btn ${textAlign === 'right' ? 'active' : ''}`}
              onClick={() => handleTextAlignChange('right')}
              title="محاذاة يمين"
            >
              ⇤
            </button>
            <button
              className={`toolbar-btn ${textAlign === 'center' ? 'active' : ''}`}
              onClick={() => handleTextAlignChange('center')}
              title="محاذاة وسط"
            >
              ⇔
            </button>
            <button
              className={`toolbar-btn ${textAlign === 'left' ? 'active' : ''}`}
              onClick={() => handleTextAlignChange('left')}
              title="محاذاة يسار"
            >
              ⇥
            </button>
          </div>

          <div className="toolbar-group">
            <input
              type="color"
              value={textColor}
              onChange={(e) => handleColorChange(e.target.value)}
              className="color-picker"
              title="لون النص"
            />
          </div>

          <div className="toolbar-group">
            <button
              className="toolbar-btn"
              onClick={() => handleFormatting('insertUnorderedList')}
              title="قائمة نقطية"
            >
              • List
            </button>
            <button
              className="toolbar-btn"
              onClick={() => handleFormatting('insertOrderedList')}
              title="قائمة مرقمة"
            >
              1. List
            </button>
          </div>

          <div className="toolbar-group">
            <button
              className="toolbar-btn"
              onClick={() => handleFormatting('undo')}
              title="تراجع"
            >
              ↶
            </button>
            <button
              className="toolbar-btn"
              onClick={() => handleFormatting('redo')}
              title="إعادة"
            >
              ↷
            </button>
          </div>
        </div>

        {/* منطقة التحرير */}
        <div
          ref={editorRef}
          className="text-editor"
          contentEditable
          onInput={(e) => setContent(e.currentTarget.innerHTML)}
          style={{
            fontSize: `${fontSize}px`,
            textAlign: textAlign as any,
            color: textColor
          }}
          suppressContentEditableWarning={true}
        >
          <p>اكتب سياسة الخصوصية هنا...</p>
        </div>

        {/* أزرار الحفظ والإلغاء */}
        <div className="editor-actions">
          <button className="save-btn" onClick={handleSave}>
            حفظ التغييرات
          </button>
          <button 
            className="cancel-btn" 
            onClick={() => {
              if (editorRef.current) {
                editorRef.current.innerHTML = '<p>اكتب سياسة الخصوصية هنا...</p>';
                setContent('');
              }
            }}
          >
            إلغاء التغييرات
          </button>
        </div>
      </div>
    </div>
  );
};

