  not_started: 'لم يبدأ',
  in_progress: 'قيد التقدم',
  completed: 'مكتمل',
  active: 'نشط',
  pending: 'معلق',
  failed: 'راسب',
  blocked: 'محظور',
  graduated: 'متخرج',
};

const translateStatus = (value: unknown): string => {
  if (typeof value !== 'string' || !value) return '-';
  return statusMap[value.toLowerCase()] || value;
};

