const fmt = (v: unknown) => {
  if (v === null || v === undefined || v === '') return '-';
  if (typeof v === 'number') return v.toLocaleString('ar-EG');
  return String(v);
};

export default function StudentsReportsIndexPage() {
  const router = useRouter();
  const [page, setPage] = useState(1);
  const [data, setData] = useState<StudentItem[]>([]);
  const [pagination, setPagination] = useState<StudentsPagination | null>(null);
  const [stats, setStats] = useState<StudentsStats | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selected, setSelected] = useState<Set<number>>(new Set());
  const [searchTerm, setSearchTerm] = useState('');

  const loadData = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);
      const res = await getStudentsStatus(page, 20);
      setData(res.data);
      setPagination(res.pagination);
      if (res.stats) setStats(res.stats);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'فشل تحميل بيانات الطلاب');
    } finally {
      setLoading(false);
    }
  }, [page]);

  useEffect(() => {
    loadData();
  }, [loadData]);

  // Selection helpers
  const toggleSelect = (id: number) => {
    setSelected(prev => {
      const next = new Set(prev);
      next.has(id) ? next.delete(id) : next.add(id);
      return next;
    });
  };

  const toggleAll = () => {
    if (selected.size === data.length) {
      setSelected(new Set());
    } else {
      setSelected(new Set(data.map(s => s.id)));
    }
  };

  const isAllSelected = data.length > 0 && selected.size === data.length;

  // Filtered data
  const filteredData = useMemo(() => {
    if (!searchTerm.trim()) return data;
    const term = searchTerm.toLowerCase();
    return data.filter(s => 
      s.name?.toLowerCase().includes(term) || 
      s.email?.toLowerCase().includes(term)
    );
  }, [data, searchTerm]);

  // Export helpers
  const exportStudents = (students: StudentItem[]) => {
    exportCSV(
      `تقارير_الطلاب_${new Date().toLocaleDateString('ar-EG')}`,
      ['الاسم', 'البريد الإلكتروني', 'المقررات المسجلة', 'المقررات المكتملة', 'الدبلومات النشطة'],
      students.map(s => [
        s.name || '-',
        s.email || '-',
        s.total_courses ?? '-',
        s.completed_courses ?? '-',
        s.active_diplomas ?? '-',
      ])
    );
  };

  const handleBulkExport = () => {
    if (selected.size > 0) {
      const selectedStudents = data.filter(s => selected.has(s.id));
      exportStudents(selectedStudents);
    } else {
      exportStudents(data);
    }
  };

  const handleBulkBlock = async () => {
    if (!confirm(`هل أنت متأكد من تعليق ${selected.size} طالب؟`)) return;
    for (const id of selected) {
      try { await blockUser(id); } catch {}
    }
    setSelected(new Set());
    loadData();
  };

  const handleBulkDelete = async () => {
    if (!confirm(`تحذير: سيتم حذف ${selected.size} طالب نهائياً. هل أنت متأكد؟`)) return;
    for (const id of selected) {
      try { await deleteUser(id); } catch {}
    }
    setSelected(new Set());
    loadData();
  };

  // Row Actions
  const handleRowBlock = async (student: StudentItem) => {
    if (!confirm(`هل تريد تعليق حساب "${student.name}"؟`)) return;
    try {
      await blockUser(student.id);
      loadData();
    } catch {}
  };

  const handleRowDelete = async (student: StudentItem) => {
    if (!confirm(`تحذير: هل تريد حذف "${student.name}" نهائياً؟`)) return;
    try {
      await deleteUser(student.id);
      loadData();
    } catch {}
  };

  return (
    <AdminPage>
      <motion.div className={styles.page} initial={{ opacity: 0 }} animate={{ opacity: 1 }}>

        {/* ─── Hero Banner ─── */}
        <div className={styles.hero}>
          <div className={styles.heroRow}>
            <div className={styles.heroText}>
              <h1>📊 تقارير الطلاب</h1>
              <p>متابعة شاملة لأداء الطلاب ومستوى تفاعلهم مع المقررات والدبلومات.</p>
            </div>
            <div className={styles.heroActions}>
              <button className={`${styles.heroBtn} ${styles.heroBtnPrimary}`} onClick={() => exportStudents(data)}>
                <Download size={18} />
                تصدير الكل
              </button>
              <button className={`${styles.heroBtn} ${styles.heroBtnSecondary}`} onClick={() => router.push('/admin/reports')}>
                <ArrowRight size={18} />
                العودة
              </button>
            </div>
          </div>
        </div>

        {/* ─── Stats Cards ─── */}
        <div className={styles.statsRow}>
          <div className={styles.statCard}>
            <div className={styles.statIcon} style={{ backgroundColor: '#f0f9ff', color: '#0ea5e9' }}>
              <Users size={22} />
            </div>
            <div className={styles.statInfo}>
              <span className={styles.statValue}>{fmt(stats?.total_students ?? pagination?.total)}</span>
              <span className={styles.statLabel}>إجمالي الطلاب</span>
            </div>
          </div>
          <div className={styles.statCard}>
            <div className={styles.statIcon} style={{ backgroundColor: '#ecfdf5', color: '#10b981' }}>
              <UserCheck size={22} />
            </div>
            <div className={styles.statInfo}>
              <span className={styles.statValue}>{fmt(stats?.active_students ?? '-')}</span>
              <span className={styles.statLabel}>الطلاب النشطين</span>
            </div>
          </div>
          <div className={styles.statCard}>
            <div className={styles.statIcon} style={{ backgroundColor: '#fff1f2', color: '#e11d48' }}>
              <ShieldAlert size={22} />
            </div>
            <div className={styles.statInfo}>
              <span className={styles.statValue}>{fmt(stats?.blocked_students ?? '-')}</span>
              <span className={styles.statLabel}>الطلاب الموقوفين</span>
            </div>
          </div>
          <div className={styles.statCard}>
            <div className={styles.statIcon} style={{ backgroundColor: '#f5f3ff', color: '#8b5cf6' }}>
              <CheckCircle size={22} />
            </div>
            <div className={styles.statInfo}>
              <span className={styles.statValue}>{fmt(pagination?.last_page)}</span>
              <span className={styles.statLabel}>عدد الصفحات</span>
            </div>
          </div>
        </div>

        {/* ─── Toolbar: Search + Bulk Actions ─── */}
        <div className={styles.toolbar}>
          <div className={styles.searchBox}>
            <Search size={18} color="#94a3b8" />
            <input 
              type="text" 
              placeholder="ابحث بالاسم أو البريد الإلكتروني..." 
              value={searchTerm}
              onChange={e => setSearchTerm(e.target.value)}
            />
          </div>

          <div className={styles.bulkActions}>
            {selected.size > 0 && (
              <>
                <span className={styles.selectionCount}>
                  تم تحديد {selected.size.toLocaleString('ar-EG')}
                </span>
                <button className={styles.bulkBtn} onClick={handleBulkExport}>
                  <Download size={16} />
                  تصدير المحدد
                </button>
                <button className={`${styles.bulkBtn} ${styles.bulkBtnDanger}`} onClick={handleBulkBlock}>
                  <Ban size={16} />
                  تعليق المحدد
                </button>
                <button className={`${styles.bulkBtn} ${styles.bulkBtnDanger}`} onClick={handleBulkDelete}>
                  <Trash2 size={16} />
                  حذف المحدد
                </button>
              </>
            )}
            <button className={styles.bulkBtn} onClick={loadData} title="تحديث البيانات">
              <RefreshCw size={16} />
            </button>
          </div>
        </div>

        {/* ─── Table ─── */}
        {loading && !data.length ? <AdminState type="loading" /> : null}
        {!loading && error ? <AdminState type="error" message={error} onAction={loadData} actionLabel="إعادة المحاولة" /> : null}
        {!loading && !error && !data.length ? <AdminState type="empty" message="لا يوجد طلاب لعرض تقاريرهم." /> : null}

        {filteredData.length > 0 && (
          <div className={styles.tableSection}>
            <div className={styles.tableHeader}>
              <div className={styles.tableTitle}>
                قائمة الطلاب
                <span className={styles.tableCount}>({fmt(pagination?.total)} طالب)</span>
              </div>
            </div>

            <div style={{ overflowX: 'auto', opacity: loading ? 0.6 : 1, transition: 'opacity 0.2s' }}>
              <table className={styles.table}>
                <thead>
                  <tr>
                    <th style={{ width: 40 }}>
                      <input 
                        type="checkbox" 
                        className={styles.checkbox}
                        checked={isAllSelected}
                        onChange={toggleAll}
                      />
                    </th>
                    <th>الطالب</th>
                    <th>المقررات</th>
                    <th>المقررات المكتملة</th>
                    <th>الدبلومات</th>
                    <th>الإجراءات</th>
                  </tr>
                </thead>
                <tbody>
                  {filteredData.map(student => (
                    <tr 
                      key={student.id} 
                      className={selected.has(student.id) ? styles.selected : ''}
                    >
                      <td>
                        <input 
                          type="checkbox" 
                          className={styles.checkbox}
                          checked={selected.has(student.id)}
                          onChange={() => toggleSelect(student.id)}
                        />
                      </td>
                      <td>
                        <div className={styles.studentCell}>
                          <div className={styles.studentAvatar}>
                            {String(student.name || '?').charAt(0).toUpperCase()}
                          </div>
                          <div>
                            <div className={styles.studentName}>{student.name}</div>
                            <div className={styles.studentEmail}>{student.email}</div>
                          </div>
                        </div>
                      </td>
                      <td>
                        <span className={`${styles.badge} ${styles.badgeBlue}`}>
                          {fmt(student.total_courses)}
                        </span>
                      </td>
                      <td>
                        <span className={`${styles.badge} ${styles.badgeGreen}`}>
                          {fmt(student.completed_courses)}
                        </span>
                      </td>
                      <td>
                        <span className={`${styles.badge} ${styles.badgePurple}`}>
                          {fmt(student.active_diplomas)}
                        </span>
                      </td>
                      <td>
                        <div className={styles.rowActions}>
                          <button 
                            className={`${styles.rowBtn} ${styles.rowBtnView}`}
                            onClick={() => router.push(`/admin/reports/students/${student.id}`)}
                            title="عرض التقرير المفصل"
                          >
                            <Eye size={14} />
                            التقرير
                          </button>
                          <button 
                            className={`${styles.rowBtn} ${styles.rowBtnBlock}`}
                            onClick={() => handleRowBlock(student)}
                            title="تعليق الحساب"
                          >
                            <Ban size={14} />
                          </button>
                          <button 
                            className={`${styles.rowBtn} ${styles.rowBtnDelete}`}
                            onClick={() => handleRowDelete(student)}
                            title="حذف الطالب"
                          >
                            <Trash2 size={14} />
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            {/* ─── Pagination ─── */}
            {pagination && (
              <div className={styles.paginationWrap}>
                <div className={styles.paginationInfo}>
                  الصفحة {pagination.current_page.toLocaleString('ar-EG')} من {pagination.last_page.toLocaleString('ar-EG')} — الإجمالي {pagination.total.toLocaleString('ar-EG')} طالب
                </div>
                <div className={styles.paginationBtns}>
                  <button 
                    disabled={pagination.current_page <= 1 || loading}
                    onClick={() => setPage(p => Math.max(1, p - 1))}
                  >
                    السابق
                  </button>
                  <button 
                    disabled={pagination.current_page >= pagination.last_page || loading}
                    onClick={() => setPage(p => p + 1)}
                  >
                    التالي
                  </button>
                </div>
              </div>
            )}
          </div>
        )}

      </motion.div>
    </AdminPage>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import styles from './Supervisors.module.css';
import apiClient from '@/utils/apiClient';

interface PagePermission {
    page: string;
    key: string;
    description: string;
}

interface Supervisor {
    id: number;
    name: string;
    email: string;
    phone: string;
    created_at: string;
    permissions: string[];
}

export default function SupervisorsPage() {
    const [supervisors, setSupervisors] = useState<Supervisor[]>([]);
    const [pages, setPages] = useState<PagePermission[]>([]);
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [success, setSuccess] = useState<string | null>(null);

    // Form state
    const [formData, setFormData] = useState({
        name: '',
        email: '',
        password: '',
        phone: '',
    });
    const [selectedPages, setSelectedPages] = useState<string[]>([]);

    // Edit modal state
    const [editingId, setEditingId] = useState<number | null>(null);
    const [editPages, setEditPages] = useState<string[]>([]);
    const [showPasswordModal, setShowPasswordModal] = useState<number | null>(null);
    const [newPassword, setNewPassword] = useState('');

    useEffect(() => {
        fetchData();
    }, []);

    const fetchData = async () => {
        try {
            setLoading(true);
            const [supervisorsRes, permissionsRes] = await Promise.all([
                apiClient.get('/admin/supervisors'),
                apiClient.get('/admin/supervisors/permissions'),
            ]);
            setSupervisors(supervisorsRes.data.data || []);
            setPages(permissionsRes.data.data || []);
        } catch (err: any) {
            setError(err.response?.data?.message || 'حدث خطأ في تحميل البيانات');
        } finally {
            setLoading(false);
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (selectedPages.length === 0) {
            setError('يجب اختيار صفحة واحدة على الأقل');
            return;
        }

        try {
            setSaving(true);
            setError(null);
            await apiClient.post('/admin/supervisors', {
                ...formData,
                permissions: selectedPages,
            });
            setSuccess('تم إنشاء المشرف بنجاح');
            setFormData({ name: '', email: '', password: '', phone: '' });
            setSelectedPages([]);
            fetchData();
        } catch (err: any) {
            const errors = err.response?.data?.errors;
            if (errors) {
                setError(Object.values(errors).flat().join(', '));
            } else {
                setError(err.response?.data?.message || 'حدث خطأ');
            }
        } finally {
            setSaving(false);
        }
    };

    const handlePageToggle = (pageKey: string, list: string[], setList: (p: string[]) => void) => {
        if (list.includes(pageKey)) {
            setList(list.filter((p) => p !== pageKey));
        } else {
            setList([...list, pageKey]);
        }
    };

    const openEditModal = (supervisor: Supervisor) => {
        setEditingId(supervisor.id);
        setEditPages([...supervisor.permissions]);
    };

    const savePermissions = async () => {
        if (!editingId) return;
        if (editPages.length === 0) {
            setError('يجب اختيار صفحة واحدة على الأقل');
            return;
        }
        try {
            setSaving(true);
            await apiClient.put(`/admin/supervisors/${editingId}/permissions`, {
                permissions: editPages,
            });
            setSuccess('تم تحديث الصلاحيات بنجاح');
            setEditingId(null);
            fetchData();
        } catch (err: any) {
            setError(err.response?.data?.message || 'حدث خطأ');
        } finally {
            setSaving(false);
        }
    };

    const savePassword = async () => {
        if (!showPasswordModal || !newPassword) return;
        try {
            setSaving(true);
            await apiClient.put(`/admin/supervisors/${showPasswordModal}/password`, {
                password: newPassword,
            });
            setSuccess('تم تغيير كلمة المرور بنجاح');
            setShowPasswordModal(null);
            setNewPassword('');
        } catch (err: any) {
            setError(err.response?.data?.message || 'حدث خطأ');
        } finally {
            setSaving(false);
        }
    };

    const deleteSupervisor = async (id: number) => {
        if (!confirm('هل أنت متأكد من حذف هذا المشرف؟')) return;
        try {
            await apiClient.delete(`/admin/supervisors/${id}`);
            setSuccess('تم حذف المشرف بنجاح');
            fetchData();
        } catch (err: any) {
            setError(err.response?.data?.message || 'حدث خطأ');
        }
    };

    // Get page name from key
    const getPageName = (key: string): string => {
        const page = pages.find(p => p.key === key);
        return page?.page || key;
    };

    useEffect(() => {
        if (success) {
            const timer = setTimeout(() => setSuccess(null), 3000);
            return () => clearTimeout(timer);
        }
    }, [success]);

    if (loading) {
        return (
            <div className={styles.container}>
                <div className={styles.loading}>جاري التحميل...</div>
            </div>
        );
    }

    return (
        <div className={styles.container}>
            <div className={styles.header}>
                <h1 className={styles.title}>إدارة المشرفين</h1>
                <p className={styles.subtitle}>إضافة وإدارة صلاحيات المشرفين</p>
            </div>

            {error && <div className={styles.error}>{error}</div>}
            {success && <div className={styles.success}>{success}</div>}

            {/* Add Supervisor Form */}
            <div className={styles.formCard}>
                <h2 className={styles.formTitle}>إضافة مشرف جديد</h2>
                <form onSubmit={handleSubmit}>
                    <div className={styles.formGrid}>
                        <div className={styles.formGroup}>
                            <label>الاسم *</label>
                            <input
                                type="text"
                                value={formData.name}
                                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                                required
                                placeholder="اسم المشرف"
                            />
                        </div>
                        <div className={styles.formGroup}>
                            <label>البريد الإلكتروني *</label>
                            <input
                                type="email"
                                value={formData.email}
                                onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                                required
                                placeholder="email@example.com"
                            />
                        </div>
                        <div className={styles.formGroup}>
                            <label>كلمة المرور *</label>
                            <input
                                type="password"
                                value={formData.password}
                                onChange={(e) => setFormData({ ...formData, password: e.target.value })}
                                required
                                placeholder="كلمة المرور"
                                minLength={6}
                            />
                        </div>
                        <div className={styles.formGroup}>
                            <label>رقم الهاتف</label>
                            <input
                                type="text"
                                value={formData.phone}
                                onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                                placeholder="رقم الهاتف (اختياري)"
                            />
                        </div>
                    </div>

                    <div className={styles.permissionsSection}>
                        <h3>الصفحات المتاحة *</h3>
                        <p className={styles.permHint}>اختر الصفحات التي يمكن للمشرف الوصول إليها</p>
                        <div className={styles.pagesGrid}>
                            {pages.map((page) => (
                                <label key={page.key} className={styles.pageCard}>
                                    <input
                                        type="checkbox"
                                        checked={selectedPages.includes(page.key)}
                                        onChange={() => handlePageToggle(page.key, selectedPages, setSelectedPages)}
                                    />
                                    <div className={styles.pageInfo}>
                                        <span className={styles.pageName}>{page.page}</span>
                                        <span className={styles.pageDesc}>{page.description}</span>
                                    </div>
                                </label>
                            ))}
                        </div>
                    </div>

                    <button type="submit" className={styles.submitBtn} disabled={saving}>
                        {saving ? 'جاري الحفظ...' : 'إضافة المشرف'}
                    </button>
                </form>
            </div>

            {/* Supervisors Table */}
            <div className={styles.tableCard}>
                <h2 className={styles.tableTitle}>المشرفون ({supervisors.length})</h2>
                {supervisors.length === 0 ? (
                    <p className={styles.emptyMsg}>لا يوجد مشرفون حالياً</p>
                ) : (
                    <div className={styles.tableWrapper}>
                        <table className={styles.table}>
                            <thead>
                                <tr>
                                    <th>#</th>
                                    <th>الاسم</th>
                                    <th>البريد الإلكتروني</th>
                                    <th>الهاتف</th>
                                    <th>الصفحات</th>
                                    <th>تاريخ الإنشاء</th>
                                    <th>الإجراءات</th>
                                </tr>
                            </thead>
                            <tbody>
                                {supervisors.map((sup, idx) => (
                                    <tr key={sup.id}>
                                        <td>{idx + 1}</td>
                                        <td>{sup.name}</td>
                                        <td>{sup.email}</td>
                                        <td>{sup.phone || '-'}</td>
                                        <td>
                                            <div className={styles.permBadges}>
                                                {sup.permissions.map(p => (
                                                    <span key={p} className={styles.permBadge}>
                                                        {getPageName(p)}
                                                    </span>
                                                ))}
                                            </div>
                                        </td>
                                        <td>{new Date(sup.created_at).toLocaleDateString('ar-EG')}</td>
                                        <td className={styles.actions}>
                                            <button className={styles.editBtn} onClick={() => openEditModal(sup)}>
                                                تعديل
                                            </button>
                                            <button className={styles.passBtn} onClick={() => setShowPasswordModal(sup.id)}>
                                                كلمة المرور
                                            </button>
                                            <button className={styles.deleteBtn} onClick={() => deleteSupervisor(sup.id)}>
                                                حذف
                                            </button>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                )}
            </div>

            {/* Edit Permissions Modal */}
            {editingId && (
                <div className={styles.modal} onClick={() => setEditingId(null)}>
                    <div className={styles.modalContent} onClick={(e) => e.stopPropagation()}>
                        <h3>تعديل الصفحات المتاحة</h3>
                        <div className={styles.pagesGrid}>
                            {pages.map((page) => (
                                <label key={page.key} className={styles.pageCard}>
                                    <input
                                        type="checkbox"
                                        checked={editPages.includes(page.key)}
                                        onChange={() => handlePageToggle(page.key, editPages, setEditPages)}
                                    />
                                    <div className={styles.pageInfo}>
                                        <span className={styles.pageName}>{page.page}</span>
                                        <span className={styles.pageDesc}>{page.description}</span>
                                    </div>
                                </label>
                            ))}
                        </div>
                        <div className={styles.modalActions}>
                            <button className={styles.saveBtn} onClick={savePermissions} disabled={saving}>
                                {saving ? 'جاري الحفظ...' : 'حفظ'}
                            </button>
                            <button className={styles.cancelBtn} onClick={() => setEditingId(null)}>
                                إلغاء
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Change Password Modal */}
            {showPasswordModal && (
                <div className={styles.modal} onClick={() => setShowPasswordModal(null)}>
                    <div className={styles.modalContent} onClick={(e) => e.stopPropagation()}>
                        <h3>تغيير كلمة المرور</h3>
                        <div className={styles.formGroup}>
                            <label>كلمة المرور الجديدة</label>
                            <input
                                type="password"
                                value={newPassword}
                                onChange={(e) => setNewPassword(e.target.value)}
                                placeholder="أدخل كلمة المرور الجديدة"
                                minLength={6}
                            />
                        </div>
                        <div className={styles.modalActions}>
                            <button className={styles.saveBtn} onClick={savePassword} disabled={saving || !newPassword}>
                                {saving ? 'جاري الحفظ...' : 'تغيير'}
                            </button>
                            <button className={styles.cancelBtn} onClick={() => setShowPasswordModal(null)}>
                                إلغاء
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

'use client';

import React, { useEffect, useState } from 'react';
import { useParams, useRouter } from 'next/navigation';
import '../../../styles/checkout.css';
import { getCourseDetails, enrollCourse, getMyEnrollments, Course } from '../../../utils/courseService';
import { isAuthenticated } from '../../../utils/authService';
import { getBackendAssetUrl } from '../../../utils/url';

const DynamicCheckoutPage: React.FC = () => {
