"use client";

import React, { useEffect, useState } from "react";
import Link from "next/link";
import styles from "./MyDiplomas.module.css";
import { getMyDiplomas, type MyDiploma } from "@/utils/categoryService";
import { getBackendAssetUrl } from "@/utils/url";
import { getDownloadUrl } from "@/utils/certificateService";

export default function MyDiplomasPage() {
  const [diplomas, setDiplomas] = useState<MyDiploma[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let mounted = true;
    const fetchData = async () => {
      setLoading(true);
      setError(null);
      try {
        const data = await getMyDiplomas();
        if (mounted) setDiplomas(data);
      } catch (e: any) {
        if (mounted) setError(e?.message || "حدث خطأ غير متوقع");
      } finally {
        if (mounted) setLoading(false);
      }
    };
    fetchData();
    return () => {
      mounted = false;
    };
  }, []);

  return (
    <div className={styles.container}>
      <h1 className={styles.title}>دبلوماتي</h1>

      {loading && <div className={styles.loading}>جاري تحميل الدبلومات...</div>}
      {error && (
        <div className={styles.error}>فشل في جلب دبلوماتك: {error}</div>
      )}

      {!loading && !error && diplomas.length === 0 && (
        <div className={styles.empty}>لم تقم بالتسجيل في أي دبلومات بعد</div>
      )}

      {!loading && !error && diplomas.length > 0 && (
        <div className={styles.grid}>
          {diplomas.map((item) => {
            const coverUrl = getBackendAssetUrl(
              item.category?.cover_image_url
            );
            const slug = item.category?.slug || String(item.category?.id || "");
            const statusLabel =
              item.status === "active"
                ? "فعال"
                : item.status === "pending_payment"
                ? "بانتظار الدفع"
                : item.status;
            const badgeClass =
              item.status === "active"
                ? styles.badgeActive
                : item.status === "pending_payment"
                ? styles.badgePending
                : styles.badgeDefault;
            return (
              <div key={`my-diploma-${slug}`} className={styles.card}>
                {coverUrl && (
                  <img
                    src={coverUrl}
                    alt={item.category?.name || "دبلومة"}
                    className={styles.image}
                  />
                )}
                <div className={styles.cardBody}>
                  <div className={styles.cardHeader}>
                    <h2 className={styles.cardTitle}>
                      {item.category?.name || "اسم الدبلومة"}
                    </h2>
                    <span className={`${styles.badge} ${badgeClass}`}>{statusLabel}</span>
                  </div>
                  {/* Progress Bar */}
                  {(() => {
                    const p = Math.max(0, Math.min(100, Math.round(item.progress || 0)));
                    return (
                      <div className={styles.progress}>
                        <div className={styles.progressTrack}>
                          <div className={styles.progressFill} style={{ width: `${p}%` }} />
                        </div>
                        <div className={styles.progressInfo}>
                          {p === 100 ? (
                            <span className={styles.completedBadge}>مكتمل</span>
                          ) : (
                            <span className={styles.progressLabel}>{p}%</span>
                          )}
                        </div>
                      </div>
                    );
                  })()}
                  <div className={styles.cardActions}>
                    <Link href={`/diplomas/${slug}`} className={styles.btn}>
                      بدء التعلم
                    </Link>
                    {item.can_download_certificate && item.certificate?.file_url && (
                      <button
                        className={styles.btn}
                        onClick={() => {
                          const url = getDownloadUrl(item.certificate!.file_url!);
                          if (url) window.open(url, "_blank");
                        }}
                      >
                        تحميل الشهادة
                      </button>
                    )}
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useEffect, useState, useRef } from 'react';
export const dynamic = 'force-dynamic';
import { useParams, useRouter, useSearchParams } from 'next/navigation';
import Link from 'next/link';
import { FiBook, FiStar, FiDollarSign, FiEye, FiPlay, FiUser } from 'react-icons/fi';
import HomeHeader from '../../../components/HomeHeader';
import Footer from '../../../components/Footer';
import ScrollToTop from '../../../components/ScrollToTop';
import { SkeletonImage, SkeletonTitle, SkeletonText, SkeletonButton, SkeletonCourseCard } from '../../../components/Skeleton';
import { ProgramArtwork } from '../../../components/brand/ProgramArtwork';
import { publicDescription, publicPrice } from '@/components/brand/publicContent';
import education from '@/components/brand/PublicEducation.module.css';
import SocialMediaFloat from '../../../components/SocialMediaFloat';
import EnrollmentInfoModal from '../../../components/EnrollmentInfoModal';
import Toast from '../../../components/Toast';
import ExamBadge from '../../../components/ExamBadge';
import '@/styles/toast.css';
import { getPublicDiplomaDetails, enrollInDiploma, getMyDiplomas, type Diploma, type MyDiploma } from '../../../utils/categoryService';
import { type Course } from '../../../utils/courseService';
import { getBackendAssetUrl } from '../../../utils/url';
import { isAuthenticated } from '../../../utils/authService';
import styles from './DiplomaDetails.module.css';

// نوسّع نوع الدبلومة ليشمل المقررات المتوقعة من الـ API
type DiplomaDetails = Diploma & { courses?: Course[] };

export default function DiplomaDetailsPage() {
  const params = useParams<{ slug: string }>();
  const router = useRouter();
  const searchParams = useSearchParams();
  const slug = params?.slug;
  const coursesRef = useRef<HTMLElement>(null);

  const [diploma, setDiploma] = useState<DiplomaDetails | null>(null);
  const [authenticated, setAuthenticated] = useState(false);
  useEffect(() => { setAuthenticated(isAuthenticated()) }, []);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const [enrollStatus, setEnrollStatus] = useState<{ type: 'idle' | 'loading' | 'success' | 'error'; message?: string }>({ type: 'idle' });
  const [isEnrollmentModalOpen, setIsEnrollmentModalOpen] = useState(false);
  const [isEnrolled, setIsEnrolled] = useState<boolean>(false);
  const [checkingEnrollment, setCheckingEnrollment] = useState<boolean>(false);
  const [toastVisible, setToastVisible] = useState(false);
  const [toastMessage, setToastMessage] = useState('');
  const [toastType, setToastType] = useState<'success' | 'error' | 'warning' | 'info' | 'confirm'>('info');

  const showToast = (message: string, type: 'success' | 'error' | 'warning' | 'info' | 'confirm' = 'info', duration = 3000) => {
    setToastMessage(message);
    setToastType(type);
    setToastVisible(true);
    if (duration > 0) {
      setTimeout(() => setToastVisible(false), duration);
    }
  };

  // Check if user is enrolled in this diploma
  const checkEnrollmentStatus = async () => {
    if (!diploma || !isAuthenticated()) {
      setIsEnrolled(false);
      return;
    }

    try {
      setCheckingEnrollment(true);
      const myDiplomas = await getMyDiplomas();
      const enrolled = myDiplomas.some((myDiploma: MyDiploma) =>
        myDiploma.category?.id === diploma.id || myDiploma.category?.slug === diploma.slug
      );
      setIsEnrolled(enrolled);
    } catch (error) {
      console.error('Error checking enrollment status:', error);
      setIsEnrolled(false);
    } finally {
      setCheckingEnrollment(false);
    }
  };

  useEffect(() => {
    const run = async () => {
      if (!slug) return;
      setLoading(true);
      setError(null);
      try {
        const data = await getPublicDiplomaDetails(String(slug));
        setDiploma(data as unknown as DiplomaDetails);
      } catch (e: any) {
        setError(e?.message || 'حدث خطأ أثناء جلب بيانات الدبلومة');
      } finally {
        setLoading(false);
      }
    };
    run();
  }, [slug]);

  // عرض تنبيه عند الوصول من صفحة المقرر بضرورة الاشتراك
