"use client";

import React, { useEffect, useMemo, useState } from "react";
import { useParams, useRouter } from "next/navigation";
import {
  startCourseFinalExam,
  submitCourseFinalExam,
  StartExamResponse,
  getActiveCourseFinalExamAttempt,
  getCourseFinalExamMeta,
} from "@/utils/quizService";
import { getCourseDetails } from "@/utils/courseService";
import Toast from "@/components/Toast";
import "@/styles/toast.css";
import styles from "./FinalExam.module.css";

export default function CourseFinalExamPage() {
  const params = useParams();
  const router = useRouter();
  const courseId = useMemo(() => Number(params?.courseId), [params]);

  const [loading, setLoading] = useState(true);
  const [courseName, setCourseName] = useState<string>("");
  const [attemptId, setAttemptId] = useState<number | null>(null);
  const [questions, setQuestions] = useState<Array<{
    id: number;
    question: string;
    options: string[];
  }>>([]);
  const [selectedAnswers, setSelectedAnswers] = useState<Record<number, number>>({});
  const [startTime, setStartTime] = useState<number>(Date.now());
  const [submitting, setSubmitting] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const [toastVisible, setToastVisible] = useState(false);
  const [toastMessage, setToastMessage] = useState("");
  const [toastType, setToastType] = useState<"success" | "error" | "warning" | "info" | "confirm">("info");

  const showToast = (
    message: string,
    type: "success" | "error" | "warning" | "info" | "confirm" = "info"
  ) => {
    setToastMessage(message);
    setToastType(type);
    setToastVisible(true);
  };

  useEffect(() => {
    let mounted = true;
    async function init() {
      if (!courseId || Number.isNaN(courseId)) {
        showToast("معرف المقرر غير صالح", "error");
        setLoading(false);
        return;
      }

      setLoading(true);
      try {
        // جلب اسم المقرر
        getCourseDetails(courseId).then((course) => {
          if (course?.title) setCourseName(course.title);
        }).catch(() => { });

        // 1) حاول استرجاع المحاولة النشطة أولاً
        const active = await getActiveCourseFinalExamAttempt(courseId);
        if (!mounted) return;
        if (active && active.attempt_id) {
          setAttemptId(Number(active.attempt_id));
          setQuestions(active.questions || []);
          setStartTime(Date.now());
          return;
        }

        // 2) إن لم توجد محاولة نشطة، افحص الميتاداتا لتحديد السماحية
        const meta = await getCourseFinalExamMeta(courseId);
        if (!mounted) return;
        const allowed = meta?.is_allowed_now === true;
        const eligible = meta?.eligible_to_start !== false; // افتراض السماحية ما لم يذكر خلاف ذلك
        if (allowed && eligible) {
          // 3) البدء عند السماح الآن
          const data: StartExamResponse = await startCourseFinalExam(courseId);
          if (!mounted) return;
          setAttemptId(data.attempt_id);
          setQuestions(data.questions);
          setStartTime(Date.now());
          return;
        }

        // 4) غير مسموح الآن → اعرض رسالة تهدئة/منع وارجع لاختباراتي
        const remaining = Number(meta?.remaining_cooldown_seconds ?? 0);
        const msg = remaining > 0
          ? `محاولة جديدة غير متاحة الآن. يمكنك إعادة المحاولة بعد ${remaining} ثانية.`
          : (meta?.next_allowed_at
            ? `محاولة جديدة غير متاحة الآن. متاح بعد ${new Date(meta.next_allowed_at).toLocaleString()}`
            : "محاولة جديدة غير متاحة الآن");
        showToast(msg, "warning");
        try {
          sessionStorage.setItem("exam-block-message", msg);
          sessionStorage.setItem("flash-toast", JSON.stringify({ message: msg, type: "warning" }));
        } catch { }
        router.replace("/user/my_exams");
      } catch (err: any) {
        // 422 بنك أسئلة غير كافٍ أو أخطاء أخرى
        const message = err?.response?.status === 422
          ? (err?.response?.data?.message || "بنك الأسئلة غير كافٍ")
          : (err?.message || "تعذر بدء الامتحان");
        showToast(message, "error");
        try {
          sessionStorage.setItem("exam-block-message", message);
          sessionStorage.setItem("flash-toast", JSON.stringify({ message, type: "error" }));
        } catch { }
        router.replace("/user/my_exams");
      } finally {
        if (mounted) setLoading(false);
      }
    }
    init();
    return () => { mounted = false; };
  }, [courseId]);

  function handleSelect(questionId: number, optionIndex: number) {
    setSelectedAnswers((prev) => ({ ...prev, [questionId]: optionIndex }));
  }

  async function handleSubmit() {
    if (!attemptId) {
      showToast("لا يوجد محاولة نشطة لهذا الامتحان", "error");
      return;
    }

    // Ensure all questions are answered
    const unanswered = questions.filter((q) => !(q.id in selectedAnswers));
    if (unanswered.length > 0) {
      showToast("من فضلك أجب على كل الأسئلة قبل الإرسال", "warning");
      return;
    }

    const answers = questions.map((q) => ({
      question_id: q.id,
      selected_indices: [selectedAnswers[q.id]],
    }));

    const time_taken = Math.max(1, Math.round((Date.now() - startTime) / 1000));

    setSubmitting(true);
    try {
      await submitCourseFinalExam(courseId, attemptId, { answers, time_taken });
      setSubmitted(true);
      showToast("تم إرسال الإجابات بنجاح", "success");
      try {
        sessionStorage.setItem(
          "flash-toast",
          JSON.stringify({ message: "تم إرسال الإجابات بنجاح", type: "success" })
        );
        // احفظ معرف المقرر لفتح تفاصيل النتائج تلقائيًا في صفحة اختباراتي
        sessionStorage.setItem("last-exam-course-id", String(courseId));
      } catch { }
      // اخرج فورًا إلى صفحة اختباراتي بدون إمكانية الرجوع لهذه الصفحة
      router.replace("/user/my_exams");
    } catch (err: any) {
      const message = err?.message || "فشل إرسال الإجابات";
      showToast(message, "error");
    } finally {
      setSubmitting(false);
    }
  }

  // إذا حاول المستخدم الرجوع لهذه الصفحة بعد الإرسال (مثل back)، أعد التوجيه
  useEffect(() => {
    function handlePageShow() {
      if (submitted) {
        router.replace("/user/my_exams");
      }
    }
    if (typeof window !== "undefined") {
      window.addEventListener("pageshow", handlePageShow);
    }
    return () => {
      if (typeof window !== "undefined") {
        window.removeEventListener("pageshow", handlePageShow);
      }
    };
  }, [submitted, router]);

  return (
    <div className={`quiz-container ${styles.finalExamPage}`}>
      <Toast
        message={toastMessage}
        type={toastType}
        isVisible={toastVisible}
        onClose={() => setToastVisible(false)}
      />
      <h1 className="question-number" style={{ marginBottom: 10 }}>
        الامتحان النهائي للمقرر{courseName ? `: ${courseName}` : ""}
      </h1>

      {loading && <p>جارِ تحميل الأسئلة...</p>}

      {!loading && questions.length === 0 && (
        <div className="question-box">
          <p>لا توجد أسئلة متاحة أو غير مؤهل لبدء الامتحان.</p>
          <div className="navigation-buttons">
            <button className="nav-button" onClick={() => router.replace("/user/my_exams")}>العودة إلى اختباراتي</button>
          </div>
        </div>
      )}

      {!loading && questions.length > 0 && (
        <>
          <div className="quiz-progress">
            تم اختيار {Object.keys(selectedAnswers).length} من {questions.length} أسئلة
          </div>
          {questions.map((q, idx) => (
            <div key={q.id} className="question-box">
              <div className="question-number">سؤال {idx + 1}</div>
              <div className="question-text">{q.question}</div>
              <div className="options-container">
                {q.options.map((opt, i) => {
                  const selected = selectedAnswers[q.id] === i;
                  return (
                    <label key={i} className={`option-item ${selected ? "selected" : ""}`}>
                      <input
                        type="radio"
                        name={`q-${q.id}`}
                        value={i}
                        className="option-radio"
                        checked={selected}
                        onChange={() => handleSelect(q.id, i)}
                      />
                      <span>{opt}</span>
                    </label>
                  );
                })}
              </div>
            </div>
          ))}

          <div className="navigation-buttons">
            <button className="finish-button" data-demo-mutation onClick={handleSubmit} disabled={submitting}>
              {submitting ? "جارِ الإرسال..." : "إرسال جميع الإجابات"}
              <span className="finish-arrow">›</span>
            </button>
          </div>
        </>
      )}
    </div>
  );
}

'use client';

import { useEffect, useState } from 'react';
import ExamCard from '../../../components/ExamCard';
import ExamDetails from '../../../components/ExamDetails';
import type { Course } from '../../../utils/courseService';
import { getCourseDetails } from '../../../utils/courseService';
import styles from '../my_courses/MyCourses.module.css';
import Toast from '../../../components/Toast';

interface SelectedExam {
  id: number;
  name: string;
  progress: number;
}

export default function MyExams() {
  const [selectedExam, setSelectedExam] = useState<SelectedExam | null>(null);
  const [toastVisible, setToastVisible] = useState(false);
  const [toastMessage, setToastMessage] = useState('');
  const [toastType, setToastType] = useState<'success' | 'error' | 'warning' | 'info' | 'confirm'>('info');

  useEffect(() => {
    try {
      const raw = sessionStorage.getItem('flash-toast');
      if (raw) {
        const data = JSON.parse(raw);
        if (data && data.message) {
          setToastMessage(String(data.message));
          setToastType((data.type as any) || 'info');
          setToastVisible(true);
        }
        sessionStorage.removeItem('flash-toast');
      }
      // دعم المفتاح البديل exam-block-message حسب توصية الباك إند
      const blockMsg = sessionStorage.getItem('exam-block-message');
      if (blockMsg) {
        setToastMessage(String(blockMsg));
        setToastType('warning');
        setToastVisible(true);
        sessionStorage.removeItem('exam-block-message');
      }
    } catch { }
  }, []);

  // افتح تفاصيل الامتحان تلقائيًا إذا كانت هناك عملية إرسال حديثة
  useEffect(() => {
    let cancelled = false;
    async function openLatestExam() {
      try {
        const lastId = sessionStorage.getItem('last-exam-course-id');
        if (!lastId) return;
        sessionStorage.removeItem('last-exam-course-id');
        const courseId = Number(lastId);
        if (!courseId || Number.isNaN(courseId)) return;
        const course = await getCourseDetails(courseId);
        if (cancelled || !course) return;
        const progress = Number(course.progress_percentage || 0);
        setSelectedExam({ id: course.id, name: course.title, progress });
      } catch (err) {
        // تجاهل أي خطأ؛ يمكن للمستخدم فتح التفاصيل يدويًا
        console.warn('Failed to auto-open latest exam details:', err);
      }
    }
    openLatestExam();
    return () => { cancelled = true; };
  }, []);

  const handleExamSelect = (course: Course) => {
    const progress = Number(course.progress_percentage || 0);
    setSelectedExam({ id: course.id, name: course.title, progress });
  };

  const handleBackToExams = () => {
    setSelectedExam(null);
  };

  return (
    <div className={`my-courses-page ${styles.myCoursesPage}`}>
      <Toast
        message={toastMessage}
        type={toastType}
        isVisible={toastVisible}
        onClose={() => setToastVisible(false)}
      />
      {!selectedExam ? (
        <>
          <div className="page-header">
            <h1>اختباراتي</h1>
            <p>جميع الاختبارات المتاحة لك</p>
          </div>

          <div className="courses-container">
            <ExamCard showAll={true} onExamSelect={handleExamSelect} />
          </div>
        </>
      ) : (
        <ExamDetails
          courseId={selectedExam.id}
          courseName={selectedExam.name}
          completionPercentage={selectedExam.progress}
          onBack={handleBackToExams}
        />
      )}
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import styles from './Settings.module.css';
import ProfileTab from '../../../components/settings/ProfileTab';
import PasswordTab from '../../../components/settings/PasswordTab';
import { getProfile, updateProfile, changePassword } from '../../../utils/authService';
import { getBackendAssetUrl } from '../../../utils/url';

export default function Settings() {
  const [profileData, setProfileData] = useState({
    firstName: '',
    lastName: '',
    email: ''
  });
  const [passwordData, setPasswordData] = useState({
    currentPassword: '',
    newPassword: '',
    confirmPassword: ''
  });
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [successMessage, setSuccessMessage] = useState('');
  const [profileImage, setProfileImage] = useState<string | null>(null);

  // Fetch profile data on component mount
  useEffect(() => {
    const fetchProfileData = async () => {
      try {
        setIsLoading(true);
        setError(null);
        const profileResponse = await getProfile();

        // Safely split the name field into firstName and lastName
        const fullName = typeof profileResponse.name === 'string' ? profileResponse.name.trim() : '';
        const nameParts = fullName ? fullName.split(' ') : [];
        const firstName = nameParts.length > 0 ? nameParts[0] : '';
        const lastName = nameParts.length > 1 ? nameParts.slice(1).join(' ') : '';

        setProfileData({
          firstName,
          lastName,
          email: (profileResponse as any).email ?? ''
        });

        // Set profile image if it exists
        if (profileResponse.profile_picture) {
          const imageUrl = getBackendAssetUrl(profileResponse.profile_picture);
          setProfileImage(imageUrl);
        }
      } catch (err) {
        console.error('Error fetching profile data:', err);
        setError(err instanceof Error ? err.message : 'حدث خطأ في جلب بيانات الملف الشخصي');
      } finally {
        setIsLoading(false);
      }
    };

    fetchProfileData();
  }, []);

  const handleProfileChange = (field: string, value: string) => {
    setProfileData(prev => ({ ...prev, [field]: value }));
  };

  const handlePasswordChange = (field: string, value: string) => {
    setPasswordData(prev => ({ ...prev, [field]: value }));
  };

  // أزلنا منطق التفضيلات بالكامل

  const handleProfileUpdate = async (e: React.FormEvent) => {
    e.preventDefault();

    setIsLoading(true);
    setError(null);
    setSuccessMessage('');

    try {
      // Combine firstName and lastName into a single name string
      const combinedName = `${profileData.firstName} ${profileData.lastName}`.trim();

      // استدعاء تحديث الملف الشخصي بإرسال الاسم فقط (كما يدعم الباك إند)
      const updatedUser = await updateProfile({
        name: combinedName,
        email: ''
      });

      // Update localStorage with fresh user data
      if (typeof window !== 'undefined') {
        localStorage.setItem('user_data', JSON.stringify(updatedUser));
      }

      // Set success message
      setSuccessMessage('تم تحديث الملف الشخصي بنجاح');

      // Clear success message after 5 seconds
      setTimeout(() => {
        setSuccessMessage('');
      }, 5000);

    } catch (err) {
      console.error('Error updating profile:', err);
      setError(err instanceof Error ? err.message : 'حدث خطأ في تحديث الملف الشخصي');
    } finally {
      setIsLoading(false);
    }
  };

  const handleSavePassword = async () => {
    setError(null);
    setSuccessMessage('');

    // Basic validations
    if (!passwordData.currentPassword) {
      setError('يرجى إدخال كلمة المرور الحالية');
      return;
    }
    if (!passwordData.newPassword) {
      setError('يرجى إدخال كلمة المرور الجديدة');
      return;
    }
    if (passwordData.newPassword !== passwordData.confirmPassword) {
      setError('تأكيد كلمة المرور لا يطابق كلمة المرور الجديدة');
      return;
    }

    try {
      setIsLoading(true);
      await changePassword({
        current_password: passwordData.currentPassword,
        password: passwordData.newPassword,
        password_confirmation: passwordData.confirmPassword,
      });

      // Reset fields on success
      setPasswordData({ currentPassword: '', newPassword: '', confirmPassword: '' });
      setSuccessMessage('تم تغيير كلمة المرور بنجاح');

      setTimeout(() => setSuccessMessage(''), 5000);
    } catch (err) {
      console.error('Error changing password:', err);
      setError(err instanceof Error ? err.message : 'حدث خطأ في تغيير كلمة المرور');
    } finally {
      setIsLoading(false);
    }
  };

  // لا توجد تفضيلات بعد الآن

  return (
    <div className={`dashboard-container settings-page ${styles.settingsPage}`}>
      <div className="settings-header">
        <h1 className="settings-title">الإعدادات</h1>
        <p className="settings-subtitle">إدارة إعدادات حسابك</p>
      </div>

      {/* Loading State */}
      {isLoading && (
        <div className="loading-container" style={{ textAlign: 'center', padding: '2rem' }}>
          <p>جاري تحميل بيانات الملف الشخصي...</p>
        </div>
      )}

      {/* Error Message - consolidated below in Error State */}

      {/* Success Message */}
      {successMessage && (
        <div className="success-message">
          {successMessage}
        </div>
      )}

      {/* Error State */}
      {error && (
        <div className="error-container" style={{ 
          backgroundColor: '#fee', 
          border: '1px solid #fcc', 
          borderRadius: '8px', 
          padding: '1rem', 
          margin: '1rem 0',
          color: '#c33'
        }}>
          <p>خطأ: {error}</p>
          <button 
            onClick={() => window.location.reload()} 
            style={{
              marginTop: '0.5rem',
              padding: '0.5rem 1rem',
              backgroundColor: '#c33',
              color: 'white',
              border: 'none',
              borderRadius: '4px',
              cursor: 'pointer'
            }}
          >
            إعادة المحاولة
          </button>
        </div>
      )}

      {/* Content - only show when not loading and no error */}
      {!isLoading && !error && (
        <>
      {/* عرض موحد: تعديل الحساب وكلمة السر في نفس الصفحة */}
      <div className="combined-settings">
        <ProfileTab 
          profileData={profileData} 
          onProfileChange={handleProfileChange}
          onSave={handleProfileUpdate}
          isLoading={isLoading}
          profileImage={profileImage}
          setProfileImage={setProfileImage}
        />

        <div style={{ marginTop: '2rem' }}>
          <PasswordTab 
            passwordData={passwordData}
            onPasswordChange={handlePasswordChange}
            onSave={handleSavePassword}
          />
        </div>
      </div>
      </>
    )}
  </div>
);
}

'use client';
