        <button onClick={onPrev} className="step-prev-btn">
          <span className="btn-icon">⬅️</span>
          السابق: المعلومات الأساسية
        </button>
        <button onClick={onNext} className="step-next-btn">
          <span className="btn-icon">➡️</span>
          التالي: مراجعة ونشر
        </button>
      </div>

      {/* Toast Component */}
      <Toast
        message={toastMessage}
        type={toastType}
        isVisible={toastVisible}
        onClose={closeToast}
      />
    </div>
  );
};

