  if (typeof window === 'undefined') return null; // Check if running on client side
  try {
    const t = window.localStorage?.getItem('auth_token');
    return t && t !== 'undefined' ? t : null;
  } catch (error) {
    console.warn('getAuthToken: localStorage unavailable', error);
    return null;
  }
};

